    DecryptRequest.add_member(:ciphertext_blob, Smithy::Schema::Shapes::ShapeRef.new(shape: CiphertextType, location_name: 'CiphertextBlob', traits: {"smithy.api#documentation" => "<p>Ciphertext to be decrypted. The blob includes metadata.</p>", "smithy.api#required" => {}}))
    DecryptRequest.add_member(:encryption_context, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionContextType, location_name: 'EncryptionContext', traits: {"smithy.api#documentation" => "<p>Specifies the encryption context to use when decrypting the data.\n      An encryption context is valid only for <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/kms-cryptography.html#cryptographic-operations\">cryptographic operations</a> with a symmetric encryption KMS key. The standard asymmetric encryption algorithms and HMAC algorithms that KMS uses do not support an encryption context.</p>\n         <p>An <i>encryption context</i> is a collection of non-secret key-value pairs that represent additional authenticated data. \nWhen you use an encryption context to encrypt data, you must specify the same (an exact case-sensitive match) encryption context to decrypt the data. An encryption context is supported\nonly on operations with symmetric encryption KMS keys. On operations with symmetric encryption KMS keys, an encryption context is optional, but it is strongly recommended.</p>\n         <p>For more information, see\n<a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/encrypt_context.html\">Encryption context</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    DecryptRequest.add_member(:grant_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: GrantTokenList, location_name: 'GrantTokens', traits: {"smithy.api#documentation" => "<p>A list of grant tokens. </p>\n         <p>Use a grant token when your permission to call this operation comes from a new grant that has not yet achieved <i>eventual consistency</i>. For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/grants.html#grant_token\">Grant token</a> and <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/using-grant-token.html\">Using a grant token</a> in the\n    <i>Key Management Service Developer Guide</i>.</p>"}))
    DecryptRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Specifies the KMS key that KMS uses to decrypt the ciphertext.</p>\n         <p>Enter a key ID of the KMS key that was used to encrypt the ciphertext. If you identify a\n      different KMS key, the <code>Decrypt</code> operation throws an\n        <code>IncorrectKeyException</code>.</p>\n         <p>This parameter is required only when the ciphertext was encrypted under an asymmetric KMS\n      key. If you used a symmetric encryption KMS key, KMS can get the KMS key from metadata that\n      it adds to the symmetric ciphertext blob. However, it is always recommended as a best\n      practice. This practice ensures that you use the KMS key that you intend.</p>\n         <p>To specify a KMS key, use its key ID, key ARN, alias name, or alias ARN. When using an alias name, prefix it with <code>\"alias/\"</code>. To specify a KMS key in a different Amazon Web Services account, you must use the key ARN or alias ARN.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias name: <code>alias/ExampleAlias</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias ARN: <code>arn:aws:kms:us-east-2:111122223333:alias/ExampleAlias</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>. To get the alias name and alias ARN, use <a>ListAliases</a>.</p>"}))
    DecryptRequest.add_member(:encryption_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionAlgorithmSpec, location_name: 'EncryptionAlgorithm', traits: {"smithy.api#documentation" => "<p>Specifies the encryption algorithm that will be used to decrypt the ciphertext. Specify\n      the same algorithm that was used to encrypt the data. If you specify a different algorithm,\n      the <code>Decrypt</code> operation fails.</p>\n         <p>This parameter is required only when the ciphertext was encrypted under an asymmetric KMS\n      key. The default value, <code>SYMMETRIC_DEFAULT</code>, represents the only supported\n      algorithm that is valid for symmetric encryption KMS keys.</p>"}))
    DecryptRequest.add_member(:recipient, Smithy::Schema::Shapes::ShapeRef.new(shape: RecipientInfo, location_name: 'Recipient', traits: {"smithy.api#documentation" => "<p>A signed <a href=\"https://docs.aws.amazon.com/enclaves/latest/user/nitro-enclave-concepts.html#term-attestdoc\">attestation\n        document</a> from an Amazon Web Services Nitro enclave and the encryption algorithm to use with the\n      enclave's public key. The only valid encryption algorithm is <code>RSAES_OAEP_SHA_256</code>. </p>\n         <p>This parameter only supports attestation documents for Amazon Web Services Nitro Enclaves. To include this\n      parameter, use the <a href=\"https://docs.aws.amazon.com/enclaves/latest/user/developing-applications.html#sdk\">Amazon Web Services Nitro Enclaves SDK</a> or any Amazon Web Services SDK.</p>\n         <p>When you use this parameter, instead of returning the plaintext data, KMS encrypts the\n      plaintext data with the public key in the attestation document, and returns the resulting\n      ciphertext in the <code>CiphertextForRecipient</code> field in the response. This ciphertext\n      can be decrypted only with the private key in the enclave. The <code>Plaintext</code> field in\n      the response is null or empty.</p>\n         <p>For information about the interaction between KMS and Amazon Web Services Nitro Enclaves, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/services-nitro-enclaves.html\">How Amazon Web Services Nitro Enclaves uses KMS</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    DecryptRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBooleanType, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks if your request will succeed. <code>DryRun</code> is an optional parameter. </p>\n         <p>To learn more about how to use this parameter, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/testing-permissions.html\">Testing your permissions</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    DecryptRequest.type = Types::DecryptRequest
    DecryptResponse.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/concepts.html#key-id-key-ARN\">key ARN</a>) of the KMS key that was used to decrypt the ciphertext.</p>"}))
    DecryptResponse.add_member(:plaintext, Smithy::Schema::Shapes::ShapeRef.new(shape: PlaintextType, location_name: 'Plaintext', traits: {"smithy.api#documentation" => "<p>Decrypted plaintext data. When you use the HTTP API or the Amazon Web Services CLI, the value is Base64-encoded. Otherwise, it is not Base64-encoded.</p>\n         <p>If the response includes the <code>CiphertextForRecipient</code> field, the\n        <code>Plaintext</code> field is null or empty.</p>"}))
    DecryptResponse.add_member(:encryption_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionAlgorithmSpec, location_name: 'EncryptionAlgorithm', traits: {"smithy.api#documentation" => "<p>The encryption algorithm that was used to decrypt the ciphertext.</p>"}))
    DecryptResponse.add_member(:ciphertext_for_recipient, Smithy::Schema::Shapes::ShapeRef.new(shape: CiphertextType, location_name: 'CiphertextForRecipient', traits: {"smithy.api#documentation" => "<p>The plaintext data encrypted with the public key in the attestation document. </p>\n         <p>This field is included in the response only when the <code>Recipient</code> parameter in\n      the request includes a valid attestation document from an Amazon Web Services Nitro enclave.\n      For information about the interaction between KMS and Amazon Web Services Nitro Enclaves, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/services-nitro-enclaves.html\">How Amazon Web Services Nitro Enclaves uses KMS</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    DecryptResponse.add_member(:key_material_id, Smithy::Schema::Shapes::ShapeRef.new(shape: BackingKeyIdType, location_name: 'KeyMaterialId', traits: {"smithy.api#documentation" => "<p>The identifier of the key material used to decrypt the ciphertext. This field is present\n      only when the operation uses a symmetric encryption KMS key. This field is omitted if the\n      request includes the <code>Recipient</code> parameter.</p>"}))
