    DeleteImportedKeyMaterialRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Identifies the KMS key from which you are deleting imported key material. The\n        <code>Origin</code> of the KMS key must be <code>EXTERNAL</code>.</p>\n         <p>Specify the key ID or key ARN of the KMS key.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>.</p>", "smithy.api#required" => {}}))
    DeleteImportedKeyMaterialRequest.add_member(:key_material_id, Smithy::Schema::Shapes::ShapeRef.new(shape: BackingKeyIdType, location_name: 'KeyMaterialId', traits: {"smithy.api#documentation" => "<p>Identifies the imported key material you are deleting. </p>\n         <important>\n            <p>If no KeyMaterialId is specified, KMS deletes the current key material.</p>\n         </important>\n         <p>To get the list of key material IDs associated with a KMS key, use <a>ListKeyRotations</a>.</p>"}))
