    DeriveSharedSecretRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Identifies an asymmetric NIST-recommended ECC or SM2 (China Regions only) KMS key. KMS\n      uses the private key in the specified key pair to derive the shared secret. The key usage of\n      the KMS key must be <code>KEY_AGREEMENT</code>. To find the <code>KeyUsage</code> of a KMS\n      key, use the <a>DescribeKey</a> operation.</p>\n         <p>To specify a KMS key, use its key ID, key ARN, alias name, or alias ARN. When using an alias name, prefix it with <code>\"alias/\"</code>. To specify a KMS key in a different Amazon Web Services account, you must use the key ARN or alias ARN.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias name: <code>alias/ExampleAlias</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias ARN: <code>arn:aws:kms:us-east-2:111122223333:alias/ExampleAlias</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>. To get the alias name and alias ARN, use <a>ListAliases</a>.</p>", "smithy.api#required" => {}}))
    DeriveSharedSecretRequest.add_member(:key_agreement_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyAgreementAlgorithmSpec, location_name: 'KeyAgreementAlgorithm', traits: {"smithy.api#documentation" => "<p>Specifies the key agreement algorithm used to derive the shared secret. The only valid\n      value is <code>ECDH</code>.</p>", "smithy.api#required" => {}}))
    DeriveSharedSecretRequest.add_member(:public_key, Smithy::Schema::Shapes::ShapeRef.new(shape: PublicKeyType, location_name: 'PublicKey', traits: {"smithy.api#documentation" => "<p>Specifies the public key in your peer's NIST-recommended elliptic curve (ECC) or SM2\n      (China Regions only) key pair.</p>\n         <p>The public key must be a DER-encoded X.509 public key, also known as\n        <code>SubjectPublicKeyInfo</code> (SPKI), as defined in <a href=\"https://tools.ietf.org/html/rfc5280\">RFC 5280</a>.</p>\n         <p>\n            <a>GetPublicKey</a> returns the public key of an asymmetric KMS key pair in the\n      required DER-encoded format.</p>\n         <note>\n            <p>If you use <a href=\"https://docs.aws.amazon.com/cli/v1/userguide/cli-chap-welcome.html\">Amazon Web Services CLI version 1</a>, you must provide the DER-encoded X.509 public key in a file.\n        Otherwise, the Amazon Web Services CLI Base64-encodes the public key a second time, resulting in a\n          <code>ValidationException</code>.</p>\n         </note>\n         <p>You can specify the public key as binary data in a file using fileb\n        (<code>fileb://<path-to-file></code>) or in-line using a Base64 encoded string.</p>", "smithy.api#required" => {}}))
    DeriveSharedSecretRequest.add_member(:grant_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: GrantTokenList, location_name: 'GrantTokens', traits: {"smithy.api#documentation" => "<p>A list of grant tokens.</p>\n         <p>Use a grant token when your permission to call this operation comes from a new grant that has not yet achieved <i>eventual consistency</i>. For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/grants.html#grant_token\">Grant token</a> and <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/using-grant-token.html\">Using a grant token</a> in the\n    <i>Key Management Service Developer Guide</i>.</p>"}))
    DeriveSharedSecretRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBooleanType, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks if your request will succeed. <code>DryRun</code> is an optional parameter. </p>\n         <p>To learn more about how to use this parameter, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/testing-permissions.html\">Testing your permissions</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    DeriveSharedSecretRequest.add_member(:recipient, Smithy::Schema::Shapes::ShapeRef.new(shape: RecipientInfo, location_name: 'Recipient', traits: {"smithy.api#documentation" => "<p>A signed <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/nitro-enclave-how.html#term-attestdoc\">attestation document</a> from\n      an Amazon Web Services Nitro enclave and the encryption algorithm to use with the enclave's public key. The\n      only valid encryption algorithm is <code>RSAES_OAEP_SHA_256</code>. </p>\n         <p>This parameter only supports attestation documents for Amazon Web Services Nitro Enclaves. To call\n      DeriveSharedSecret for an Amazon Web Services Nitro Enclaves, use the <a href=\"https://docs.aws.amazon.com/enclaves/latest/user/developing-applications.html#sdk\">Amazon Web Services Nitro Enclaves SDK</a> to generate the\n      attestation document and then use the Recipient parameter from any Amazon Web Services SDK to provide the\n      attestation document for the enclave.</p>\n         <p>When you use this parameter, instead of returning a plaintext copy of the shared secret,\n      KMS encrypts the plaintext shared secret under the public key in the attestation document,\n      and returns the resulting ciphertext in the <code>CiphertextForRecipient</code> field in the\n      response. This ciphertext can be decrypted only with the private key in the enclave. The\n        <code>CiphertextBlob</code> field in the response contains the encrypted shared secret\n      derived from the KMS key specified by the <code>KeyId</code> parameter and public key\n      specified by the <code>PublicKey</code> parameter. The <code>SharedSecret</code> field in the\n      response is null or empty.</p>\n         <p>For information about the interaction between KMS and Amazon Web Services Nitro Enclaves, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/services-nitro-enclaves.html\">How Amazon Web Services Nitro Enclaves uses KMS</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    DeriveSharedSecretRequest.type = Types::DeriveSharedSecretRequest
    DeriveSharedSecretResponse.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Identifies the KMS key used to derive the shared secret.</p>"}))
    DeriveSharedSecretResponse.add_member(:shared_secret, Smithy::Schema::Shapes::ShapeRef.new(shape: PlaintextType, location_name: 'SharedSecret', traits: {"smithy.api#documentation" => "<p>The raw secret derived from the specified key agreement algorithm, private key in the\n      asymmetric KMS key, and your peer's public key.</p>\n         <p>If the response includes the <code>CiphertextForRecipient</code> field, the\n        <code>SharedSecret</code> field is null or empty.</p>"}))
    DeriveSharedSecretResponse.add_member(:ciphertext_for_recipient, Smithy::Schema::Shapes::ShapeRef.new(shape: CiphertextType, location_name: 'CiphertextForRecipient', traits: {"smithy.api#documentation" => "<p>The plaintext shared secret encrypted with the public key in the attestation\n      document.</p>\n         <p>This field is included in the response only when the <code>Recipient</code> parameter in\n      the request includes a valid attestation document from an Amazon Web Services Nitro enclave.\n      For information about the interaction between KMS and Amazon Web Services Nitro Enclaves, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/services-nitro-enclaves.html\">How Amazon Web Services Nitro Enclaves uses KMS</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    DeriveSharedSecretResponse.add_member(:key_agreement_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyAgreementAlgorithmSpec, location_name: 'KeyAgreementAlgorithm', traits: {"smithy.api#documentation" => "<p>Identifies the key agreement algorithm used to derive the shared secret.</p>"}))
    DeriveSharedSecretResponse.add_member(:key_origin, Smithy::Schema::Shapes::ShapeRef.new(shape: OriginType, location_name: 'KeyOrigin', traits: {"smithy.api#documentation" => "<p>The source of the key material for the specified KMS key.</p>\n         <p>When this value is <code>AWS_KMS</code>, KMS created the key material. When this value\n      is <code>EXTERNAL</code>, the key material was imported or the KMS key doesn't have any key\n      material.</p>\n         <p>The only valid values for DeriveSharedSecret are <code>AWS_KMS</code> and\n        <code>EXTERNAL</code>. DeriveSharedSecret does not support KMS keys with a\n        <code>KeyOrigin</code> value of <code>AWS_CLOUDHSM</code> or\n      <code>EXTERNAL_KEY_STORE</code>.</p>"}))
    DeriveSharedSecretResponse.type = Types::DeriveSharedSecretResponse
    DescribeCustomKeyStoresRequest.add_member(:custom_key_store_id, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomKeyStoreIdType, location_name: 'CustomKeyStoreId', traits: {"smithy.api#documentation" => "<p>Gets only information about the specified custom key store. Enter the key store ID.</p>\n         <p>By default, this operation gets information about all custom key stores in the account and\n      Region. To limit the output to a particular custom key store, provide either the\n        <code>CustomKeyStoreId</code> or <code>CustomKeyStoreName</code> parameter, but not\n      both.</p>"}))
    DescribeCustomKeyStoresRequest.add_member(:custom_key_store_name, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomKeyStoreNameType, location_name: 'CustomKeyStoreName', traits: {"smithy.api#documentation" => "<p>Gets only information about the specified custom key store. Enter the friendly name of the\n      custom key store.</p>\n         <p>By default, this operation gets information about all custom key stores in the account and\n      Region. To limit the output to a particular custom key store, provide either the\n        <code>CustomKeyStoreId</code> or <code>CustomKeyStoreName</code> parameter, but not\n      both.</p>"}))
    DescribeCustomKeyStoresRequest.add_member(:limit, Smithy::Schema::Shapes::ShapeRef.new(shape: LimitType, location_name: 'Limit', traits: {"smithy.api#documentation" => "<p>Use this parameter to specify the maximum number of items to return. When this\n    value is present, KMS does not return more than the specified number of items, but it might\n    return fewer.</p>"}))
    DescribeCustomKeyStoresRequest.add_member(:marker, Smithy::Schema::Shapes::ShapeRef.new(shape: MarkerType, location_name: 'Marker', traits: {"smithy.api#documentation" => "<p>Use this parameter in a subsequent request after you receive a response with\n    truncated results. Set it to the value of <code>NextMarker</code> from the truncated response\n    you just received.</p>"}))
