    DescribeCustomKeyStoresResponse.add_member(:truncated, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'Truncated', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>A flag that indicates whether there are more items in the list. When this\n    value is true, the list in this response is truncated. To get more items, pass the value of\n    the <code>NextMarker</code> element in this response to the <code>Marker</code> parameter in a\n    subsequent request.</p>"}))
