    EnableKeyRotationRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Identifies a symmetric encryption KMS key. You cannot enable automatic rotation of <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/symmetric-asymmetric.html\">asymmetric KMS keys</a>, <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/hmac.html\">HMAC KMS keys</a>, KMS keys with <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/importing-keys.html\">imported key material</a>, or KMS keys in a <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-store-overview.html\">custom key store</a>. To enable or disable automatic rotation of a set of related <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/rotate-keys.html#multi-region-rotate\">multi-Region keys</a>, set the property on the primary key.</p>\n         <p>Specify the key ID or key ARN of the KMS key.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>.</p>", "smithy.api#required" => {}}))
    EnableKeyRotationRequest.add_member(:rotation_period_in_days, Smithy::Schema::Shapes::ShapeRef.new(shape: RotationPeriodInDaysType, location_name: 'RotationPeriodInDays', traits: {"smithy.api#documentation" => "<p>Use this parameter to specify a custom period of time between each rotation date. If no\n      value is specified, the default value is 365 days.</p>\n         <p>The rotation period defines the number of days after you enable automatic key rotation\n      that KMS will rotate your key material, and the number of days between each automatic\n      rotation thereafter.</p>\n         <p>You can use the <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/conditions-kms.html#conditions-kms-rotation-period-in-days\">\n               <code>kms:RotationPeriodInDays</code>\n            </a> condition key to further constrain the\n      values that principals can specify in the <code>RotationPeriodInDays</code> parameter.</p>\n         <p> </p>"}))
    EnableKeyRotationRequest.type = Types::EnableKeyRotationRequest
    EncryptRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Identifies the KMS key to use in the encryption operation. The KMS key must have a\n        <code>KeyUsage</code> of <code>ENCRYPT_DECRYPT</code>. To find the <code>KeyUsage</code> of\n      a KMS key, use the <a>DescribeKey</a> operation.</p>\n         <p>To specify a KMS key, use its key ID, key ARN, alias name, or alias ARN. When using an alias name, prefix it with <code>\"alias/\"</code>. To specify a KMS key in a different Amazon Web Services account, you must use the key ARN or alias ARN.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias name: <code>alias/ExampleAlias</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias ARN: <code>arn:aws:kms:us-east-2:111122223333:alias/ExampleAlias</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>. To get the alias name and alias ARN, use <a>ListAliases</a>.</p>", "smithy.api#required" => {}}))
    EncryptRequest.add_member(:plaintext, Smithy::Schema::Shapes::ShapeRef.new(shape: PlaintextType, location_name: 'Plaintext', traits: {"smithy.api#documentation" => "<p>Data to be encrypted.</p>", "smithy.api#required" => {}}))
    EncryptRequest.add_member(:encryption_context, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionContextType, location_name: 'EncryptionContext', traits: {"smithy.api#documentation" => "<p>Specifies the encryption context that will be used to encrypt the data.\n      An encryption context is valid only for <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/kms-cryptography.html#cryptographic-operations\">cryptographic operations</a> with a symmetric encryption KMS key. The standard asymmetric encryption algorithms and HMAC algorithms that KMS uses do not support an encryption context. </p>\n         <important>\n            <p>Do not include confidential or sensitive information in this field. This field may be displayed in plaintext in CloudTrail logs and other output.</p>\n         </important>\n         <p>An <i>encryption context</i> is a collection of non-secret key-value pairs that represent additional authenticated data. \nWhen you use an encryption context to encrypt data, you must specify the same (an exact case-sensitive match) encryption context to decrypt the data. An encryption context is supported\nonly on operations with symmetric encryption KMS keys. On operations with symmetric encryption KMS keys, an encryption context is optional, but it is strongly recommended.</p>\n         <p>For more information, see\n<a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/encrypt_context.html\">Encryption context</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    EncryptRequest.add_member(:grant_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: GrantTokenList, location_name: 'GrantTokens', traits: {"smithy.api#documentation" => "<p>A list of grant tokens.</p>\n         <p>Use a grant token when your permission to call this operation comes from a new grant that has not yet achieved <i>eventual consistency</i>. For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/grants.html#grant_token\">Grant token</a> and <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/using-grant-token.html\">Using a grant token</a> in the\n    <i>Key Management Service Developer Guide</i>.</p>"}))
    EncryptRequest.add_member(:encryption_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionAlgorithmSpec, location_name: 'EncryptionAlgorithm', traits: {"smithy.api#documentation" => "<p>Specifies the encryption algorithm that KMS will use to encrypt the plaintext message.\n      The algorithm must be compatible with the KMS key that you specify.</p>\n         <p>This parameter is required only for asymmetric KMS keys. The default value,\n        <code>SYMMETRIC_DEFAULT</code>, is the algorithm used for symmetric encryption KMS keys. If\n      you are using an asymmetric KMS key, we recommend RSAES_OAEP_SHA_256.</p>\n         <p>The SM2PKE algorithm is only available in China Regions.</p>"}))
    EncryptRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBooleanType, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks if your request will succeed. <code>DryRun</code> is an optional parameter. </p>\n         <p>To learn more about how to use this parameter, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/testing-permissions.html\">Testing your permissions</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
