    GenerateDataKeyPairRequest.add_member(:encryption_context, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionContextType, location_name: 'EncryptionContext', traits: {"smithy.api#documentation" => "<p>Specifies the encryption context that will be used when encrypting the private key in the\n      data key pair.</p>\n         <important>\n            <p>Do not include confidential or sensitive information in this field. This field may be displayed in plaintext in CloudTrail logs and other output.</p>\n         </important>\n         <p>An <i>encryption context</i> is a collection of non-secret key-value pairs that represent additional authenticated data. \nWhen you use an encryption context to encrypt data, you must specify the same (an exact case-sensitive match) encryption context to decrypt the data. An encryption context is supported\nonly on operations with symmetric encryption KMS keys. On operations with symmetric encryption KMS keys, an encryption context is optional, but it is strongly recommended.</p>\n         <p>For more information, see\n<a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/encrypt_context.html\">Encryption context</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    GenerateDataKeyPairRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Specifies the symmetric encryption KMS key that encrypts the private key in the data key\n      pair. You cannot specify an asymmetric KMS key or a KMS key in a custom key store. To get the\n      type and origin of your KMS key, use the <a>DescribeKey</a> operation.</p>\n         <p>To specify a KMS key, use its key ID, key ARN, alias name, or alias ARN. When using an alias name, prefix it with <code>\"alias/\"</code>. To specify a KMS key in a different Amazon Web Services account, you must use the key ARN or alias ARN.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias name: <code>alias/ExampleAlias</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias ARN: <code>arn:aws:kms:us-east-2:111122223333:alias/ExampleAlias</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>. To get the alias name and alias ARN, use <a>ListAliases</a>.</p>", "smithy.api#required" => {}}))
    GenerateDataKeyPairRequest.add_member(:key_pair_spec, Smithy::Schema::Shapes::ShapeRef.new(shape: DataKeyPairSpec, location_name: 'KeyPairSpec', traits: {"smithy.api#documentation" => "<p>Determines the type of data key pair that is generated. </p>\n         <p>The KMS rule that restricts the use of asymmetric RSA and SM2 KMS keys to encrypt and decrypt or to sign and verify (but not both), the rule that permits you to use ECC KMS keys only to sign and verify, and the rule that permits you to use ML-DSA key pairs to sign and verify only are not effective on data key pairs, which are used outside of KMS. The SM2 key spec is only available in China Regions.</p>", "smithy.api#required" => {}}))
    GenerateDataKeyPairRequest.add_member(:grant_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: GrantTokenList, location_name: 'GrantTokens', traits: {"smithy.api#documentation" => "<p>A list of grant tokens.</p>\n         <p>Use a grant token when your permission to call this operation comes from a new grant that has not yet achieved <i>eventual consistency</i>. For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/grants.html#grant_token\">Grant token</a> and <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/using-grant-token.html\">Using a grant token</a> in the\n    <i>Key Management Service Developer Guide</i>.</p>"}))
    GenerateDataKeyPairRequest.add_member(:recipient, Smithy::Schema::Shapes::ShapeRef.new(shape: RecipientInfo, location_name: 'Recipient', traits: {"smithy.api#documentation" => "<p>A signed <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/nitro-enclave-how.html#term-attestdoc\">attestation document</a> from\n      an Amazon Web Services Nitro enclave and the encryption algorithm to use with the enclave's public key. The\n      only valid encryption algorithm is <code>RSAES_OAEP_SHA_256</code>. </p>\n         <p>This parameter only supports attestation documents for Amazon Web Services Nitro Enclaves. To call\n      DeriveSharedSecret for an Amazon Web Services Nitro Enclaves, use the <a href=\"https://docs.aws.amazon.com/enclaves/latest/user/developing-applications.html#sdk\">Amazon Web Services Nitro Enclaves SDK</a> to generate the\n      attestation document and then use the Recipient parameter from any Amazon Web Services SDK to provide the\n      attestation document for the enclave.</p>\n         <p>When you use this parameter, instead of returning a plaintext copy of the private data\n      key, KMS encrypts the plaintext private data key under the public key in the attestation\n      document, and returns the resulting ciphertext in the <code>CiphertextForRecipient</code>\n      field in the response. This ciphertext can be decrypted only with the private key in the\n      enclave. The <code>CiphertextBlob</code> field in the response contains a copy of the private\n      data key encrypted under the KMS key specified by the <code>KeyId</code> parameter. The\n        <code>PrivateKeyPlaintext</code> field in the response is null or empty.</p>\n         <p>For information about the interaction between KMS and Amazon Web Services Nitro Enclaves, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/services-nitro-enclaves.html\">How Amazon Web Services Nitro Enclaves uses KMS</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    GenerateDataKeyPairRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBooleanType, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks if your request will succeed. <code>DryRun</code> is an optional parameter. </p>\n         <p>To learn more about how to use this parameter, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/testing-permissions.html\">Testing your permissions</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    GenerateDataKeyPairRequest.type = Types::GenerateDataKeyPairRequest
    GenerateDataKeyPairResponse.add_member(:private_key_ciphertext_blob, Smithy::Schema::Shapes::ShapeRef.new(shape: CiphertextType, location_name: 'PrivateKeyCiphertextBlob', traits: {"smithy.api#documentation" => "<p>The encrypted copy of the private key. When you use the HTTP API or the Amazon Web Services CLI, the value is Base64-encoded. Otherwise, it is not Base64-encoded.</p>"}))
    GenerateDataKeyPairResponse.add_member(:private_key_plaintext, Smithy::Schema::Shapes::ShapeRef.new(shape: PlaintextType, location_name: 'PrivateKeyPlaintext', traits: {"smithy.api#documentation" => "<p>The plaintext copy of the private key. When you use the HTTP API or the Amazon Web Services CLI, the value is Base64-encoded. Otherwise, it is not Base64-encoded.</p>\n         <p>If the response includes the <code>CiphertextForRecipient</code> field, the\n        <code>PrivateKeyPlaintext</code> field is null or empty.</p>"}))
