    GetKeyRotationStatusResponse.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Identifies the specified symmetric encryption KMS key.</p>"}))
