    GetKeyRotationStatusResponse.add_member(:next_rotation_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'NextRotationDate', traits: {"smithy.api#documentation" => "<p>The next date that KMS will automatically rotate the key material.</p>"}))
    GetKeyRotationStatusResponse.add_member(:on_demand_rotation_start_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'OnDemandRotationStartDate', traits: {"smithy.api#documentation" => "<p>Identifies the date and time that an in progress on-demand rotation was initiated.</p>\n         <p>KMS uses a background process to perform rotations. As a result, there might be a slight\n      delay between initiating on-demand key rotation and the rotation's completion. Once the\n      on-demand rotation is complete, KMS removes this field from the response. You can use <a>ListKeyRotations</a> to view the details of the completed on-demand rotation.</p>"}))
