    GetParametersForImportResponse.add_member(:public_key, Smithy::Schema::Shapes::ShapeRef.new(shape: PlaintextType, location_name: 'PublicKey', traits: {"smithy.api#documentation" => "<p>The public key to use to encrypt the key material before importing it with <a>ImportKeyMaterial</a>.</p>"}))
    GetParametersForImportResponse.add_member(:parameters_valid_to, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'ParametersValidTo', traits: {"smithy.api#documentation" => "<p>The time at which the import token and public key are no longer valid. After this time,\n      you cannot use them to make an <a>ImportKeyMaterial</a> request and you must send\n      another <code>GetParametersForImport</code> request to get new ones.</p>"}))
    GetParametersForImportResponse.type = Types::GetParametersForImportResponse
    GetPublicKeyRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Identifies the asymmetric KMS key that includes the public key.</p>\n         <p>To specify a KMS key, use its key ID, key ARN, alias name, or alias ARN. When using an alias name, prefix it with <code>\"alias/\"</code>. To specify a KMS key in a different Amazon Web Services account, you must use the key ARN or alias ARN.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias name: <code>alias/ExampleAlias</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias ARN: <code>arn:aws:kms:us-east-2:111122223333:alias/ExampleAlias</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>. To get the alias name and alias ARN, use <a>ListAliases</a>.</p>", "smithy.api#required" => {}}))
    GetPublicKeyRequest.add_member(:grant_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: GrantTokenList, location_name: 'GrantTokens', traits: {"smithy.api#documentation" => "<p>A list of grant tokens.</p>\n         <p>Use a grant token when your permission to call this operation comes from a new grant that has not yet achieved <i>eventual consistency</i>. For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/grants.html#grant_token\">Grant token</a> and <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/using-grant-token.html\">Using a grant token</a> in the\n    <i>Key Management Service Developer Guide</i>.</p>"}))
    GetPublicKeyRequest.type = Types::GetPublicKeyRequest
    GetPublicKeyResponse.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/concepts.html#key-id-key-ARN\">key ARN</a>) of the asymmetric KMS key from which the public key was\n      downloaded.</p>"}))
    GetPublicKeyResponse.add_member(:public_key, Smithy::Schema::Shapes::ShapeRef.new(shape: PublicKeyType, location_name: 'PublicKey', traits: {"smithy.api#documentation" => "<p>The exported public key. </p>\n         <p>The value is a DER-encoded X.509 public key, also known as\n        <code>SubjectPublicKeyInfo</code> (SPKI), as defined in <a href=\"https://tools.ietf.org/html/rfc5280\">RFC 5280</a>. When you use the HTTP API or the Amazon Web Services CLI, the value is Base64-encoded. Otherwise, it is not Base64-encoded.</p>\n         <p></p>"}))
    GetPublicKeyResponse.add_member(:customer_master_key_spec, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomerMasterKeySpec, location_name: 'CustomerMasterKeySpec', traits: {"smithy.api#deprecated" => {"message" => "This field has been deprecated. Instead, use the KeySpec field."}, "smithy.api#documentation" => "<p>Instead, use the <code>KeySpec</code> field in the <code>GetPublicKey</code>\n      response.</p>\n         <p>The <code>KeySpec</code> and <code>CustomerMasterKeySpec</code> fields have the same\n      value. We recommend that you use the <code>KeySpec</code> field in your code. However, to\n      avoid breaking changes, KMS supports both fields.</p>"}))
    GetPublicKeyResponse.add_member(:key_spec, Smithy::Schema::Shapes::ShapeRef.new(shape: KeySpec, location_name: 'KeySpec', traits: {"smithy.api#documentation" => "<p>The type of the of the public key that was downloaded.</p>"}))
    GetPublicKeyResponse.add_member(:key_usage, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyUsageType, location_name: 'KeyUsage', traits: {"smithy.api#documentation" => "<p>The permitted use of the public key. Valid values for asymmetric key pairs are\n        <code>ENCRYPT_DECRYPT</code>, <code>SIGN_VERIFY</code>, and <code>KEY_AGREEMENT</code>. </p>\n         <p>This information is critical. For example, if a public key with <code>SIGN_VERIFY</code>\n      key usage encrypts data outside of KMS, the ciphertext cannot be decrypted. </p>"}))
    GetPublicKeyResponse.add_member(:encryption_algorithms, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionAlgorithmSpecList, location_name: 'EncryptionAlgorithms', traits: {"smithy.api#documentation" => "<p>The encryption algorithms that KMS supports for this key. </p>\n         <p>This information is critical. If a public key encrypts data outside of KMS by using an\n      unsupported encryption algorithm, the ciphertext cannot be decrypted. </p>\n         <p>This field appears in the response only when the <code>KeyUsage</code> of the public key\n      is <code>ENCRYPT_DECRYPT</code>.</p>"}))
    GetPublicKeyResponse.add_member(:signing_algorithms, Smithy::Schema::Shapes::ShapeRef.new(shape: SigningAlgorithmSpecList, location_name: 'SigningAlgorithms', traits: {"smithy.api#documentation" => "<p>The signing algorithms that KMS supports for this key.</p>\n         <p>This field appears in the response only when the <code>KeyUsage</code> of the public key\n      is <code>SIGN_VERIFY</code>.</p>"}))
    GetPublicKeyResponse.add_member(:key_agreement_algorithms, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyAgreementAlgorithmSpecList, location_name: 'KeyAgreementAlgorithms', traits: {"smithy.api#documentation" => "<p>The key agreement algorithm used to derive a shared secret. This field is present only\n      when the KMS key has a <code>KeyUsage</code> value of <code>KEY_AGREEMENT</code>.</p>"}))
    GetPublicKeyResponse.type = Types::GetPublicKeyResponse
    GrantConstraints.add_member(:encryption_context_subset, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionContextType, location_name: 'EncryptionContextSubset', traits: {"smithy.api#documentation" => "<p>A list of key-value pairs that must be included in the encryption context of the\n      <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/kms-cryptography.html#cryptographic-operations\">cryptographic operation</a> request. The grant allows the cryptographic operation only when the encryption\n      context in the request includes the key-value pairs specified in this constraint, although it\n      can include additional key-value pairs.</p>"}))
    GrantConstraints.add_member(:encryption_context_equals, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionContextType, location_name: 'EncryptionContextEquals', traits: {"smithy.api#documentation" => "<p>A list of key-value pairs that must match the encryption context in the <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/kms-cryptography.html#cryptographic-operations\">cryptographic operation</a>\n      request. The grant allows the operation only when the encryption context in the request is the\n      same as the encryption context specified in this constraint.</p>"}))
