    GrantListEntry.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: GrantNameType, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The friendly name that identifies the grant. If a name was provided in the <a>CreateGrant</a> request, that name is returned. Otherwise this value is null.</p>"}))
