    GrantListEntry.add_member(:grantee_principal, Smithy::Schema::Shapes::ShapeRef.new(shape: PrincipalIdType, location_name: 'GranteePrincipal', traits: {"smithy.api#documentation" => "<p>The identity that gets the permissions in the grant.</p>\n         <p>The <code>GranteePrincipal</code> field in the <code>ListGrants</code> response usually contains the\n        user or role designated as the grantee principal in the grant. However, when the grantee\n        principal in the grant is an Amazon Web Services service, the <code>GranteePrincipal</code> field contains\n        the <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_policies_elements_principal.html#principal-services\">service\n          principal</a>, which might represent several different grantee principals.</p>"}))
    GrantListEntry.add_member(:retiring_principal, Smithy::Schema::Shapes::ShapeRef.new(shape: PrincipalIdType, location_name: 'RetiringPrincipal', traits: {"smithy.api#documentation" => "<p>The principal that can retire the grant.</p>"}))
    GrantListEntry.add_member(:issuing_account, Smithy::Schema::Shapes::ShapeRef.new(shape: PrincipalIdType, location_name: 'IssuingAccount', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services account under which the grant was issued.</p>"}))
