    GrantListEntry.add_member(:constraints, Smithy::Schema::Shapes::ShapeRef.new(shape: GrantConstraints, location_name: 'Constraints', traits: {"smithy.api#documentation" => "<p>A list of key-value pairs that must be present in the encryption context of certain\n      subsequent operations that the grant allows.</p>"}))
