    KeyMetadata.add_member(:aws_account_id, Smithy::Schema::Shapes::ShapeRef.new(shape: AWSAccountIdType, location_name: 'AWSAccountId', traits: {"smithy.api#documentation" => "<p>The twelve-digit account ID of the Amazon Web Services account that owns the KMS key.</p>"}))
    KeyMetadata.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>The globally unique identifier for the KMS key.</p>", "smithy.api#required" => {}}))
    KeyMetadata.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ArnType, location_name: 'Arn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the KMS key. For examples, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws-arns-and-namespaces.html#arn-syntax-kms\">Key Management Service (KMS)</a> in the Example ARNs section of the <i>Amazon Web Services General\n        Reference</i>.</p>"}))
    KeyMetadata.add_member(:creation_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'CreationDate', traits: {"smithy.api#documentation" => "<p>The date and time when the KMS key was created.</p>"}))
    KeyMetadata.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'Enabled', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Specifies whether the KMS key is enabled. When <code>KeyState</code> is\n        <code>Enabled</code> this value is true, otherwise it is false.</p>"}))
    KeyMetadata.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: DescriptionType, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>The description of the KMS key.</p>"}))
    KeyMetadata.add_member(:key_usage, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyUsageType, location_name: 'KeyUsage', traits: {"smithy.api#documentation" => "<p>The <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/kms-cryptography.html#cryptographic-operations\">cryptographic operations</a> for which you can use the KMS key.</p>"}))
    KeyMetadata.add_member(:key_state, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyState, location_name: 'KeyState', traits: {"smithy.api#documentation" => "<p>The current status of the KMS key.</p>\n         <p>For more information about how key state affects the use of a KMS key, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-state.html\">Key states of KMS keys</a> in\n      the <i>Key Management Service Developer Guide</i>.</p>"}))
    KeyMetadata.add_member(:deletion_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'DeletionDate', traits: {"smithy.api#documentation" => "<p>The date and time after which KMS deletes this KMS key. This value is present only when\n      the KMS key is scheduled for deletion, that is, when its <code>KeyState</code> is\n        <code>PendingDeletion</code>.</p>\n         <p>When the primary key in a multi-Region key is scheduled for deletion but still has replica\n      keys, its key state is <code>PendingReplicaDeletion</code> and the length of its waiting\n      period is displayed in the <code>PendingDeletionWindowInDays</code> field.</p>"}))
    KeyMetadata.add_member(:valid_to, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'ValidTo', traits: {"smithy.api#documentation" => "<p>The earliest time at which any imported key material permanently associated with this KMS\n      key expires. When a key material expires, KMS deletes the key material and the KMS key\n      becomes unusable. This value is present only for KMS keys whose <code>Origin</code> is\n        <code>EXTERNAL</code> and the <code>ExpirationModel</code> is\n        <code>KEY_MATERIAL_EXPIRES</code>, otherwise this value is omitted.</p>"}))
    KeyMetadata.add_member(:origin, Smithy::Schema::Shapes::ShapeRef.new(shape: OriginType, location_name: 'Origin', traits: {"smithy.api#documentation" => "<p>The source of the key material for the KMS key. When this value is <code>AWS_KMS</code>,\n      KMS created the key material. When this value is <code>EXTERNAL</code>, the key material was\n      imported or the KMS key doesn't have any key material. When this value is\n        <code>AWS_CLOUDHSM</code>, the key material was created in the CloudHSM cluster associated with\n      a custom key store.</p>"}))
    KeyMetadata.add_member(:custom_key_store_id, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomKeyStoreIdType, location_name: 'CustomKeyStoreId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-store-overview.html\">custom key store</a> that contains the KMS key. This field is\n      present only when the KMS key is created in a custom key store.</p>"}))
    KeyMetadata.add_member(:cloud_hsm_cluster_id, Smithy::Schema::Shapes::ShapeRef.new(shape: CloudHsmClusterIdType, location_name: 'CloudHsmClusterId', traits: {"smithy.api#documentation" => "<p>The cluster ID of the CloudHSM cluster that contains the key material for the KMS key. When\n      you create a KMS key in an CloudHSM <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-store-overview.html\">custom key store</a>, KMS creates the key material for the KMS\n      key in the associated CloudHSM cluster. This field is present only when the KMS key is created in\n      an CloudHSM key store.</p>"}))
    KeyMetadata.add_member(:expiration_model, Smithy::Schema::Shapes::ShapeRef.new(shape: ExpirationModelType, location_name: 'ExpirationModel', traits: {"smithy.api#documentation" => "<p>Specifies whether the KMS key's key material expires. This value is present only when\n        <code>Origin</code> is <code>EXTERNAL</code>, otherwise this value is omitted.</p>"}))
    KeyMetadata.add_member(:key_manager, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyManagerType, location_name: 'KeyManager', traits: {"smithy.api#documentation" => "<p>The manager of the KMS key. KMS keys in your Amazon Web Services account are either customer managed or\n      Amazon Web Services managed. For more information about the difference, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/concepts.html#kms_keys\">KMS keys</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    KeyMetadata.add_member(:customer_master_key_spec, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomerMasterKeySpec, location_name: 'CustomerMasterKeySpec', traits: {"smithy.api#deprecated" => {"message" => "This field has been deprecated. Instead, use the KeySpec field."}, "smithy.api#documentation" => "<p>Instead, use the <code>KeySpec</code> field.</p>\n         <p>The <code>KeySpec</code> and <code>CustomerMasterKeySpec</code> fields have the same\n      value. We recommend that you use the <code>KeySpec</code> field in your code. However, to\n      avoid breaking changes, KMS supports both fields.</p>"}))
    KeyMetadata.add_member(:key_spec, Smithy::Schema::Shapes::ShapeRef.new(shape: KeySpec, location_name: 'KeySpec', traits: {"smithy.api#documentation" => "<p>Describes the type of key material in the KMS key.</p>"}))
    KeyMetadata.add_member(:encryption_algorithms, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionAlgorithmSpecList, location_name: 'EncryptionAlgorithms', traits: {"smithy.api#documentation" => "<p>The encryption algorithms that the KMS key supports. You cannot use the KMS key with other\n      encryption algorithms within KMS.</p>\n         <p>This value is present only when the <code>KeyUsage</code> of the KMS key is\n        <code>ENCRYPT_DECRYPT</code>.</p>"}))
    KeyMetadata.add_member(:signing_algorithms, Smithy::Schema::Shapes::ShapeRef.new(shape: SigningAlgorithmSpecList, location_name: 'SigningAlgorithms', traits: {"smithy.api#documentation" => "<p>The signing algorithms that the KMS key supports. You cannot use the KMS key with other\n      signing algorithms within KMS.</p>\n         <p>This field appears only when the <code>KeyUsage</code> of the KMS key is\n        <code>SIGN_VERIFY</code>.</p>"}))
    KeyMetadata.add_member(:key_agreement_algorithms, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyAgreementAlgorithmSpecList, location_name: 'KeyAgreementAlgorithms', traits: {"smithy.api#documentation" => "<p>The key agreement algorithm used to derive a shared secret.</p>"}))
    KeyMetadata.add_member(:multi_region, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBooleanType, location_name: 'MultiRegion', traits: {"smithy.api#documentation" => "<p>Indicates whether the KMS key is a multi-Region (<code>True</code>) or regional\n        (<code>False</code>) key. This value is <code>True</code> for multi-Region primary and\n      replica keys and <code>False</code> for regional KMS keys.</p>\n         <p>For more information about multi-Region keys, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/multi-region-keys-overview.html\">Multi-Region keys in KMS</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    KeyMetadata.add_member(:multi_region_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: MultiRegionConfiguration, location_name: 'MultiRegionConfiguration', traits: {"smithy.api#documentation" => "<p>Lists the primary and replica keys in same multi-Region key. This field is present only\n      when the value of the <code>MultiRegion</code> field is <code>True</code>.</p>\n         <p>For more information about any listed KMS key, use the <a>DescribeKey</a>\n      operation.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>MultiRegionKeyType</code> indicates whether the KMS key is a\n            <code>PRIMARY</code> or <code>REPLICA</code> key.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PrimaryKey</code> displays the key ARN and Region of the primary key. This field\n          displays the current KMS key if it is the primary key.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ReplicaKeys</code> displays the key ARNs and Regions of all replica keys. This\n          field includes the current KMS key if it is a replica key.</p>\n            </li>\n         </ul>"}))
    KeyMetadata.add_member(:pending_deletion_window_in_days, Smithy::Schema::Shapes::ShapeRef.new(shape: PendingWindowInDaysType, location_name: 'PendingDeletionWindowInDays', traits: {"smithy.api#documentation" => "<p>The waiting period before the primary key in a multi-Region key is deleted. This waiting\n      period begins when the last of its replica keys is deleted. This value is present only when\n      the <code>KeyState</code> of the KMS key is <code>PendingReplicaDeletion</code>. That\n      indicates that the KMS key is the primary key in a multi-Region key, it is scheduled for\n      deletion, and it still has existing replica keys.</p>\n         <p>When a single-Region KMS key or a multi-Region replica key is scheduled for deletion, its\n      deletion date is displayed in the <code>DeletionDate</code> field. However, when the primary\n      key in a multi-Region key is scheduled for deletion, its waiting period doesn't begin until\n      all of its replica keys are deleted. This value displays that waiting period. When the last\n      replica key in the multi-Region key is deleted, the <code>KeyState</code> of the scheduled\n      primary key changes from <code>PendingReplicaDeletion</code> to <code>PendingDeletion</code>\n      and the deletion date appears in the <code>DeletionDate</code> field.</p>"}))
    KeyMetadata.add_member(:mac_algorithms, Smithy::Schema::Shapes::ShapeRef.new(shape: MacAlgorithmSpecList, location_name: 'MacAlgorithms', traits: {"smithy.api#documentation" => "<p>The message authentication code (MAC) algorithm that the HMAC KMS key supports.</p>\n         <p>This value is present only when the <code>KeyUsage</code> of the KMS key is\n        <code>GENERATE_VERIFY_MAC</code>.</p>"}))
    KeyMetadata.add_member(:xks_key_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: XksKeyConfigurationType, location_name: 'XksKeyConfiguration', traits: {"smithy.api#documentation" => "<p>Information about the external key that is associated with a KMS key in an external key\n      store.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/keystore-external.html#concept-external-key\">External key</a> in the\n      <i>Key Management Service Developer Guide</i>.</p>"}))
    KeyMetadata.add_member(:current_key_material_id, Smithy::Schema::Shapes::ShapeRef.new(shape: BackingKeyIdType, location_name: 'CurrentKeyMaterialId', traits: {"smithy.api#documentation" => "<p>Identifies the current key material. This value is present for symmetric encryption keys\n      with <code>AWS_KMS</code> origin and single-Region, symmetric encryption keys with\n        <code>EXTERNAL</code> origin. These KMS keys support automatic or on-demand key rotation and\n      can have multiple key materials associated with them. KMS uses the current key material for\n      both encryption and decryption, and the non-current key material for decryption operations\n      only.</p>"}))
