    PutKeyPolicyRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Sets the key policy on the specified KMS key.</p>\n         <p>Specify the key ID or key ARN of the KMS key.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>.</p>", "smithy.api#required" => {}}))
    PutKeyPolicyRequest.add_member(:policy_name, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyNameType, location_name: 'PolicyName', traits: {"smithy.api#documentation" => "<p>The name of the key policy. If no policy name is specified, the default value is\n        <code>default</code>. The only valid value is <code>default</code>.</p>"}))
    PutKeyPolicyRequest.add_member(:policy, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyType, location_name: 'Policy', traits: {"smithy.api#documentation" => "<p>The key policy to attach to the KMS key.</p>\n         <p>The key policy must meet the following criteria:</p>\n         <ul>\n            <li>\n               <p>The key policy must allow the calling principal to make a\n          subsequent <code>PutKeyPolicy</code> request on the KMS key.  This reduces the risk that\n          the KMS key becomes unmanageable. For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-policy-default.html#prevent-unmanageable-key\">Default key policy</a> in the <i>Key Management Service Developer Guide</i>. (To omit\n          this condition, set <code>BypassPolicyLockoutSafetyCheck</code> to true.)</p>\n            </li>\n            <li>\n               <p>Each statement in the key policy must contain one or more principals. The principals\n          in the key policy must exist and be visible to KMS. When you create a new Amazon Web Services\n          principal, you might need to enforce a delay before including the new principal in a key\n          policy because the new principal might not be immediately visible to KMS. For more\n          information, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/troubleshoot_general.html#troubleshoot_general_eventual-consistency\">Changes that I make are not always immediately visible</a> in the <i>Amazon Web Services\n            Identity and Access Management User Guide</i>.</p>\n            </li>\n         </ul>\n         <note>\n            <p>If either of the required <code>Resource</code> or <code>Action</code> elements are\n        missing from a key policy statement, the policy statement has no effect. When a key policy\n        statement is missing one of these elements, the KMS console correctly reports an error,\n        but the <code>PutKeyPolicy</code> API request succeeds, even though the policy statement is\n        ineffective.</p>\n            <p>For more information on required key policy elements, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-policy-overview.html#key-policy-elements\">Elements in a key\n          policy</a> in the <i>Key Management Service Developer Guide</i>.</p>\n         </note>\n         <p>A key policy document can include only the following characters:</p>\n         <ul>\n            <li>\n               <p>Printable ASCII characters from the space character (<code>\\u0020</code>) through the end of the ASCII character range.</p>\n            </li>\n            <li>\n               <p>Printable characters in the Basic Latin and Latin-1 Supplement character set (through <code>\\u00FF</code>).</p>\n            </li>\n            <li>\n               <p>The tab (<code>\\u0009</code>), line feed (<code>\\u000A</code>), and carriage return (<code>\\u000D</code>) special characters</p>\n            </li>\n         </ul>\n         <note>\n            <p>If the key policy exceeds the length constraint, KMS returns a\n          <code>LimitExceededException</code>.</p>\n         </note>\n         <p>For information about key policies, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-policies.html\">Key policies in KMS</a> in the\n      <i>Key Management Service Developer Guide</i>.For help writing and formatting a JSON policy document, see the <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_policies.html\">IAM JSON Policy Reference</a> in the <i>\n               <i>Identity and Access Management User Guide</i>\n            </i>.</p>", "smithy.api#required" => {}}))
    PutKeyPolicyRequest.add_member(:bypass_policy_lockout_safety_check, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'BypassPolicyLockoutSafetyCheck', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Skips (\"bypasses\") the key policy lockout safety check. The default value is false.</p>\n         <important>\n            <p>Setting this value to true increases the risk that the KMS key becomes unmanageable. Do\n        not set this value to true indiscriminately.</p>\n            <p>For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-policy-default.html#prevent-unmanageable-key\">Default key policy</a> in the <i>Key Management Service Developer Guide</i>.</p>\n         </important>\n         <p>Use this parameter only when you intend to prevent the principal that is making the\n      request from making a subsequent <a href=\"https://docs.aws.amazon.com/kms/latest/APIReference/API_PutKeyPolicy.html\">PutKeyPolicy</a>\n      request on the KMS key.</p>"}))
    PutKeyPolicyRequest.type = Types::PutKeyPolicyRequest
    ReEncryptRequest.add_member(:ciphertext_blob, Smithy::Schema::Shapes::ShapeRef.new(shape: CiphertextType, location_name: 'CiphertextBlob', traits: {"smithy.api#documentation" => "<p>Ciphertext of the data to reencrypt.</p>", "smithy.api#required" => {}}))
    ReEncryptRequest.add_member(:source_encryption_context, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionContextType, location_name: 'SourceEncryptionContext', traits: {"smithy.api#documentation" => "<p>Specifies the encryption context to use to decrypt the ciphertext. Enter the same\n      encryption context that was used to encrypt the ciphertext.</p>\n         <p>An <i>encryption context</i> is a collection of non-secret key-value pairs that represent additional authenticated data. \nWhen you use an encryption context to encrypt data, you must specify the same (an exact case-sensitive match) encryption context to decrypt the data. An encryption context is supported\nonly on operations with symmetric encryption KMS keys. On operations with symmetric encryption KMS keys, an encryption context is optional, but it is strongly recommended.</p>\n         <p>For more information, see\n<a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/encrypt_context.html\">Encryption context</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    ReEncryptRequest.add_member(:source_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'SourceKeyId', traits: {"smithy.api#documentation" => "<p>Specifies the KMS key that KMS will use to decrypt the ciphertext before it is\n      re-encrypted.</p>\n         <p>Enter a key ID of the KMS key that was used to encrypt the ciphertext. If you identify a\n      different KMS key, the <code>ReEncrypt</code> operation throws an\n        <code>IncorrectKeyException</code>.</p>\n         <p>This parameter is required only when the ciphertext was encrypted under an asymmetric KMS\n      key. If you used a symmetric encryption KMS key, KMS can get the KMS key from metadata that\n      it adds to the symmetric ciphertext blob. However, it is always recommended as a best\n      practice. This practice ensures that you use the KMS key that you intend.</p>\n         <p>To specify a KMS key, use its key ID, key ARN, alias name, or alias ARN. When using an alias name, prefix it with <code>\"alias/\"</code>. To specify a KMS key in a different Amazon Web Services account, you must use the key ARN or alias ARN.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias name: <code>alias/ExampleAlias</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias ARN: <code>arn:aws:kms:us-east-2:111122223333:alias/ExampleAlias</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>. To get the alias name and alias ARN, use <a>ListAliases</a>.</p>"}))
    ReEncryptRequest.add_member(:destination_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'DestinationKeyId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the KMS key that is used to reencrypt the data. Specify a\n      symmetric encryption KMS key or an asymmetric KMS key with a <code>KeyUsage</code> value of\n        <code>ENCRYPT_DECRYPT</code>. To find the <code>KeyUsage</code> value of a KMS key, use the\n        <a>DescribeKey</a> operation.</p>\n         <p>To specify a KMS key, use its key ID, key ARN, alias name, or alias ARN. When using an alias name, prefix it with <code>\"alias/\"</code>. To specify a KMS key in a different Amazon Web Services account, you must use the key ARN or alias ARN.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias name: <code>alias/ExampleAlias</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias ARN: <code>arn:aws:kms:us-east-2:111122223333:alias/ExampleAlias</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>. To get the alias name and alias ARN, use <a>ListAliases</a>.</p>", "smithy.api#required" => {}}))
    ReEncryptRequest.add_member(:destination_encryption_context, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionContextType, location_name: 'DestinationEncryptionContext', traits: {"smithy.api#documentation" => "<p>Specifies that encryption context to use when the reencrypting the data.</p>\n         <important>\n            <p>Do not include confidential or sensitive information in this field. This field may be displayed in plaintext in CloudTrail logs and other output.</p>\n         </important>\n         <p>A destination encryption context is valid only when the destination KMS key is a symmetric\n      encryption KMS key. The standard ciphertext format for asymmetric KMS keys does not include\n      fields for metadata.</p>\n         <p>An <i>encryption context</i> is a collection of non-secret key-value pairs that represent additional authenticated data. \nWhen you use an encryption context to encrypt data, you must specify the same (an exact case-sensitive match) encryption context to decrypt the data. An encryption context is supported\nonly on operations with symmetric encryption KMS keys. On operations with symmetric encryption KMS keys, an encryption context is optional, but it is strongly recommended.</p>\n         <p>For more information, see\n<a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/encrypt_context.html\">Encryption context</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    ReEncryptRequest.add_member(:source_encryption_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionAlgorithmSpec, location_name: 'SourceEncryptionAlgorithm', traits: {"smithy.api#documentation" => "<p>Specifies the encryption algorithm that KMS will use to decrypt the ciphertext before it\n      is reencrypted. The default value, <code>SYMMETRIC_DEFAULT</code>, represents the algorithm\n      used for symmetric encryption KMS keys.</p>\n         <p>Specify the same algorithm that was used to encrypt the ciphertext. If you specify a\n      different algorithm, the decrypt attempt fails.</p>\n         <p>This parameter is required only when the ciphertext was encrypted under an asymmetric KMS\n      key.</p>"}))
    ReEncryptRequest.add_member(:destination_encryption_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionAlgorithmSpec, location_name: 'DestinationEncryptionAlgorithm', traits: {"smithy.api#documentation" => "<p>Specifies the encryption algorithm that KMS will use to reecrypt the data after it has\n      decrypted it. The default value, <code>SYMMETRIC_DEFAULT</code>, represents the encryption\n      algorithm used for symmetric encryption KMS keys.</p>\n         <p>This parameter is required only when the destination KMS key is an asymmetric KMS\n      key.</p>"}))
    ReEncryptRequest.add_member(:grant_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: GrantTokenList, location_name: 'GrantTokens', traits: {"smithy.api#documentation" => "<p>A list of grant tokens.</p>\n         <p>Use a grant token when your permission to call this operation comes from a new grant that has not yet achieved <i>eventual consistency</i>. For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/grants.html#grant_token\">Grant token</a> and <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/using-grant-token.html\">Using a grant token</a> in the\n    <i>Key Management Service Developer Guide</i>.</p>"}))
    ReEncryptRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBooleanType, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks if your request will succeed. <code>DryRun</code> is an optional parameter. </p>\n         <p>To learn more about how to use this parameter, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/testing-permissions.html\">Testing your permissions</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    ReEncryptRequest.type = Types::ReEncryptRequest
    ReEncryptResponse.add_member(:ciphertext_blob, Smithy::Schema::Shapes::ShapeRef.new(shape: CiphertextType, location_name: 'CiphertextBlob', traits: {"smithy.api#documentation" => "<p>The reencrypted data. When you use the HTTP API or the Amazon Web Services CLI, the value is Base64-encoded. Otherwise, it is not Base64-encoded.</p>"}))
    ReEncryptResponse.add_member(:source_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'SourceKeyId', traits: {"smithy.api#documentation" => "<p>Unique identifier of the KMS key used to originally encrypt the data.</p>"}))
    ReEncryptResponse.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/concepts.html#key-id-key-ARN\">key ARN</a>) of the KMS key that was used to reencrypt the data.</p>"}))
    ReEncryptResponse.add_member(:source_encryption_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionAlgorithmSpec, location_name: 'SourceEncryptionAlgorithm', traits: {"smithy.api#documentation" => "<p>The encryption algorithm that was used to decrypt the ciphertext before it was\n      reencrypted.</p>"}))
    ReEncryptResponse.add_member(:destination_encryption_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionAlgorithmSpec, location_name: 'DestinationEncryptionAlgorithm', traits: {"smithy.api#documentation" => "<p>The encryption algorithm that was used to reencrypt the data.</p>"}))
    ReEncryptResponse.add_member(:source_key_material_id, Smithy::Schema::Shapes::ShapeRef.new(shape: BackingKeyIdType, location_name: 'SourceKeyMaterialId', traits: {"smithy.api#documentation" => "<p>The identifier of the key material used to originally encrypt the data. This field is\n      present only when the original encryption used a symmetric encryption KMS key.</p>"}))
    ReEncryptResponse.add_member(:destination_key_material_id, Smithy::Schema::Shapes::ShapeRef.new(shape: BackingKeyIdType, location_name: 'DestinationKeyMaterialId', traits: {"smithy.api#documentation" => "<p>The identifier of the key material used to reencrypt the data. This field is present only\n      when data is reencrypted using a symmetric encryption KMS key.</p>"}))
    ReEncryptResponse.type = Types::ReEncryptResponse
    RecipientInfo.add_member(:key_encryption_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyEncryptionMechanism, location_name: 'KeyEncryptionAlgorithm', traits: {"smithy.api#documentation" => "<p>The encryption algorithm that KMS should use with the public key for an Amazon Web Services Nitro\n      Enclave to encrypt plaintext values for the response. The only valid value is\n        <code>RSAES_OAEP_SHA_256</code>.</p>"}))
    RecipientInfo.add_member(:attestation_document, Smithy::Schema::Shapes::ShapeRef.new(shape: AttestationDocumentType, location_name: 'AttestationDocument', traits: {"smithy.api#documentation" => "<p>The attestation document for an Amazon Web Services Nitro Enclave. This document includes the enclave's\n      public key.</p>"}))
    RecipientInfo.type = Types::RecipientInfo
    ReplicateKeyRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Identifies the multi-Region primary key that is being replicated. To determine whether a\n      KMS key is a multi-Region primary key, use the <a>DescribeKey</a> operation to\n      check the value of the <code>MultiRegionKeyType</code> property.</p>\n         <p>Specify the key ID or key ARN of a multi-Region primary key.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>mrk-1234abcd12ab34cd56ef1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/mrk-1234abcd12ab34cd56ef1234567890ab</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>.</p>", "smithy.api#required" => {}}))
    ReplicateKeyRequest.add_member(:replica_region, Smithy::Schema::Shapes::ShapeRef.new(shape: RegionType, location_name: 'ReplicaRegion', traits: {"smithy.api#documentation" => "<p>The Region ID of the Amazon Web Services Region for this replica key. </p>\n         <p>Enter the Region ID, such as <code>us-east-1</code> or <code>ap-southeast-2</code>. For a\n      list of Amazon Web Services Regions in which KMS is supported, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/kms.html#kms_region\">KMS service endpoints</a> in the\n      <i>Amazon Web Services General Reference</i>.</p>\n         <p>The replica must be in a different Amazon Web Services Region than its primary key and other replicas of\n      that primary key, but in the same Amazon Web Services partition. KMS must be available in the replica\n      Region. If the Region is not enabled by default, the Amazon Web Services account must be enabled in the\n      Region. For information about Amazon Web Services partitions, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws-arns-and-namespaces.html\">Amazon Resource Names (ARNs)</a> in the\n      <i>Amazon Web Services General Reference</i>. For information about enabling and disabling Regions, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/rande-manage.html#rande-manage-enable\">Enabling a\n        Region</a> and <a href=\"https://docs.aws.amazon.com/general/latest/gr/rande-manage.html#rande-manage-disable\">Disabling a Region</a> in the\n      <i>Amazon Web Services General Reference</i>.</p>", "smithy.api#required" => {}}))
    ReplicateKeyRequest.add_member(:policy, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyType, location_name: 'Policy', traits: {"smithy.api#documentation" => "<p>The key policy to attach to the KMS key. This parameter is optional. If you do not provide\n      a key policy, KMS attaches the <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-policy-default.html\">default key policy</a> to the KMS key.</p>\n         <p>The key policy is not a shared property of multi-Region keys. You can specify the same key\n      policy or a different key policy for each key in a set of related multi-Region keys. KMS\n      does not synchronize this property.</p>\n         <p>If you provide a key policy, it must meet the following criteria:</p>\n         <ul>\n            <li>\n               <p>The key policy must allow the calling principal to make a\n          subsequent <code>PutKeyPolicy</code> request on the KMS key.  This reduces the risk that\n          the KMS key becomes unmanageable. For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-policy-default.html#prevent-unmanageable-key\">Default key policy</a> in the <i>Key Management Service Developer Guide</i>. (To omit\n          this condition, set <code>BypassPolicyLockoutSafetyCheck</code> to true.)</p>\n            </li>\n            <li>\n               <p>Each statement in the key policy must contain one or more principals. The principals\n          in the key policy must exist and be visible to KMS. When you create a new Amazon Web Services\n          principal, you might need to enforce a delay before including the new principal in a key\n          policy because the new principal might not be immediately visible to KMS. For more\n          information, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/troubleshoot_general.html#troubleshoot_general_eventual-consistency\">Changes that I make are not always immediately visible</a> in the <i>Amazon Web Services\n            Identity and Access Management User Guide</i>.</p>\n            </li>\n         </ul>\n         <p>A key policy document can include only the following characters:</p>\n         <ul>\n            <li>\n               <p>Printable ASCII characters from the space character (<code>\\u0020</code>) through the end of the ASCII character range.</p>\n            </li>\n            <li>\n               <p>Printable characters in the Basic Latin and Latin-1 Supplement character set (through <code>\\u00FF</code>).</p>\n            </li>\n            <li>\n               <p>The tab (<code>\\u0009</code>), line feed (<code>\\u000A</code>), and carriage return (<code>\\u000D</code>) special characters</p>\n            </li>\n         </ul>\n         <p>For information about key policies, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-policies.html\">Key policies in KMS</a> in the <i>Key Management Service Developer Guide</i>.\n      For help writing and formatting a JSON policy document, see the <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_policies.html\">IAM JSON Policy Reference</a> in the <i>\n               <i>Identity and Access Management User Guide</i>\n            </i>.</p>"}))
    ReplicateKeyRequest.add_member(:bypass_policy_lockout_safety_check, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'BypassPolicyLockoutSafetyCheck', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Skips (\"bypasses\") the key policy lockout safety check. The default value is false.</p>\n         <important>\n            <p>Setting this value to true increases the risk that the KMS key becomes unmanageable. Do\n        not set this value to true indiscriminately.</p>\n            <p>For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-policy-default.html#prevent-unmanageable-key\">Default key policy</a> in the <i>Key Management Service Developer Guide</i>.</p>\n         </important>\n         <p>Use this parameter only when you intend to prevent the principal that is making the\n      request from making a subsequent <a href=\"https://docs.aws.amazon.com/kms/latest/APIReference/API_PutKeyPolicy.html\">PutKeyPolicy</a>\n      request on the KMS key.</p>"}))
    ReplicateKeyRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: DescriptionType, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the KMS key. The default value is an empty string (no\n      description).</p>\n         <important>\n            <p>Do not include confidential or sensitive information in this field. This field may be displayed in plaintext in CloudTrail logs and other output.</p>\n         </important>\n         <p>The description is not a shared property of multi-Region keys. You can specify the same\n      description or a different description for each key in a set of related multi-Region keys.\n      KMS does not synchronize this property.</p>"}))
    ReplicateKeyRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Assigns one or more tags to the replica key. Use this parameter to tag the KMS key when it\n      is created. To tag an existing KMS key, use the <a>TagResource</a>\n      operation.</p>\n         <important>\n            <p>Do not include confidential or sensitive information in this field. This field may be displayed in plaintext in CloudTrail logs and other output.</p>\n         </important>\n         <note>\n            <p>Tagging or untagging a KMS key can allow or deny permission to the KMS key. For details, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/abac.html\">ABAC for KMS</a> in the <i>Key Management Service Developer Guide</i>.</p>\n         </note>\n         <p>To use this parameter, you must have <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/kms-api-permissions-reference.html\">kms:TagResource</a> permission in an IAM policy.</p>\n         <p>Tags are not a shared property of multi-Region keys. You can specify the same tags or\n      different tags for each key in a set of related multi-Region keys. KMS does not synchronize\n      this property.</p>\n         <p>Each tag consists of a tag key and a tag value. Both the tag key and the tag value are\n      required, but the tag value can be an empty (null) string. You cannot have more than one tag\n      on a KMS key with the same tag key. If you specify an existing tag key with a different tag\n      value, KMS replaces the current tag value with the specified one.</p>\n         <p>When you add tags to an Amazon Web Services resource, Amazon Web Services generates a cost allocation\n              report with usage and costs aggregated by tags. Tags can also be used to control access to a KMS key. For details,\n              see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/tagging-keys.html\">Tags in KMS</a>.</p>"}))
    ReplicateKeyRequest.type = Types::ReplicateKeyRequest
    ReplicateKeyResponse.add_member(:replica_key_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyMetadata, location_name: 'ReplicaKeyMetadata', traits: {"smithy.api#documentation" => "<p>Displays details about the new replica key, including its Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/concepts.html#key-id-key-ARN\">key ARN</a>) and\n      <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-state.html\">Key states of KMS keys</a>. It also includes the ARN and Amazon Web Services Region of its primary key and other\n      replica keys.</p>"}))
    ReplicateKeyResponse.add_member(:replica_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyType, location_name: 'ReplicaPolicy', traits: {"smithy.api#documentation" => "<p>The key policy of the new replica key. The value is a key policy document in JSON\n      format.</p>"}))
    ReplicateKeyResponse.add_member(:replica_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'ReplicaTags', traits: {"smithy.api#documentation" => "<p>The tags on the new replica key. The value is a list of tag key and tag value\n      pairs.</p>"}))
    ReplicateKeyResponse.type = Types::ReplicateKeyResponse
    RetireGrantRequest.add_member(:grant_token, Smithy::Schema::Shapes::ShapeRef.new(shape: GrantTokenType, location_name: 'GrantToken', traits: {"smithy.api#documentation" => "<p>Identifies the grant to be retired. You can use a grant token to identify a new grant even\n      before it has achieved eventual consistency.</p>\n         <p>Only the <a>CreateGrant</a> operation returns a grant token. For details, see\n        <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/grants.html#grant_token\">Grant token</a>\n      and <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/grants.html#terms-eventual-consistency\">Eventual consistency</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    RetireGrantRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>The key ARN KMS key associated with the grant. To find the key ARN, use the <a>ListKeys</a> operation.</p>\n         <p>For example: <code>arn:aws:kms:us-east-2:444455556666:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n         </p>"}))
    RetireGrantRequest.add_member(:grant_id, Smithy::Schema::Shapes::ShapeRef.new(shape: GrantIdType, location_name: 'GrantId', traits: {"smithy.api#documentation" => "<p>Identifies the grant to retire. To get the grant ID, use <a>CreateGrant</a>,\n        <a>ListGrants</a>, or <a>ListRetirableGrants</a>.</p>\n         <ul>\n            <li>\n               <p>Grant ID Example -\n          0123456789012345678901234567890123456789012345678901234567890123</p>\n            </li>\n         </ul>"}))
    RetireGrantRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBooleanType, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks if your request will succeed. <code>DryRun</code> is an optional parameter. </p>\n         <p>To learn more about how to use this parameter, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/testing-permissions.html\">Testing your permissions</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    RetireGrantRequest.type = Types::RetireGrantRequest
    RevokeGrantRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the KMS key associated with the grant. To get the key ID and key\n      ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>.</p>\n         <p>Specify the key ID or key ARN of the KMS key. To specify a KMS key in a\ndifferent Amazon Web Services account, you must use the key ARN.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>.</p>", "smithy.api#required" => {}}))
    RevokeGrantRequest.add_member(:grant_id, Smithy::Schema::Shapes::ShapeRef.new(shape: GrantIdType, location_name: 'GrantId', traits: {"smithy.api#documentation" => "<p>Identifies the grant to revoke. To get the grant ID, use <a>CreateGrant</a>,\n        <a>ListGrants</a>, or <a>ListRetirableGrants</a>.</p>", "smithy.api#required" => {}}))
    RevokeGrantRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBooleanType, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks if your request will succeed. <code>DryRun</code> is an optional parameter. </p>\n         <p>To learn more about how to use this parameter, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/testing-permissions.html\">Testing your permissions</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    RevokeGrantRequest.type = Types::RevokeGrantRequest
    RotateKeyOnDemandRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Identifies a symmetric encryption KMS key. You cannot perform on-demand rotation of <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/symmetric-asymmetric.html\">asymmetric KMS\n        keys</a>, <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/hmac.html\">HMAC KMS\n      keys</a>, multi-Region KMS keys with <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/importing-keys.html\">imported key material</a>, or KMS keys in a\n      <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-store-overview.html\">custom key store</a>. To perform on-demand rotation of a set of related <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/rotate-keys.html#multi-region-rotate\">multi-Region\n        keys</a>, invoke the on-demand rotation on the primary key.</p>\n         <p>Specify the key ID or key ARN of the KMS key.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>.</p>", "smithy.api#required" => {}}))
    RotateKeyOnDemandRequest.type = Types::RotateKeyOnDemandRequest
    RotateKeyOnDemandResponse.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Identifies the symmetric encryption KMS key that you initiated on-demand rotation\n      on.</p>"}))
    RotateKeyOnDemandResponse.type = Types::RotateKeyOnDemandResponse
    RotationType.add_member(:automatic, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'AUTOMATIC', traits: {"smithy.api#enumValue" => "AUTOMATIC"}))
    RotationType.add_member(:on_demand, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ON_DEMAND', traits: {"smithy.api#enumValue" => "ON_DEMAND"}))
    RotationsList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: RotationsListEntry)
    RotationsListEntry.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Unique identifier of the key.</p>"}))
    RotationsListEntry.add_member(:key_material_id, Smithy::Schema::Shapes::ShapeRef.new(shape: BackingKeyIdType, location_name: 'KeyMaterialId', traits: {"smithy.api#documentation" => "<p>Unique identifier of the key material. </p>"}))
    RotationsListEntry.add_member(:key_material_description, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyMaterialDescriptionType, location_name: 'KeyMaterialDescription', traits: {"smithy.api#documentation" => "<p>User-specified description of the key material. This field is only present for symmetric\n      encryption KMS keys with <code>EXTERNAL</code> origin.</p>"}))
    RotationsListEntry.add_member(:import_state, Smithy::Schema::Shapes::ShapeRef.new(shape: ImportState, location_name: 'ImportState', traits: {"smithy.api#documentation" => "<p>Indicates if the key material is currently imported into KMS. It has two possible\n      values: <code>IMPORTED</code> or <code>PENDING_IMPORT</code>. This field is only present for\n      symmetric encryption KMS keys with <code>EXTERNAL</code> origin.</p>"}))
    RotationsListEntry.add_member(:key_material_state, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyMaterialState, location_name: 'KeyMaterialState', traits: {"smithy.api#documentation" => "<p>There are three possible values for this field: <code>CURRENT</code>,\n        <code>NON_CURRENT</code> and <code>PENDING_ROTATION</code>. KMS uses <code>CURRENT</code>\n      key material for both encryption and decryption and <code>NON_CURRENT</code> key material only\n      for decryption. <code>PENDING_ROTATION</code> identifies key material that has been imported\n      for on-demand key rotation but the rotation hasn't completed. Key material in\n        <code>PENDING_ROTATION</code> is not permanently associated with the KMS key. You can delete\n      this key material and import different key material in its place. The\n        <code>PENDING_ROTATION</code> value is only used in symmetric encryption keys with imported\n      key material. The other values, <code>CURRENT</code> and <code>NON_CURRENT</code>, are used\n      for all KMS keys that support automatic or on-demand key rotation.</p>"}))
    RotationsListEntry.add_member(:expiration_model, Smithy::Schema::Shapes::ShapeRef.new(shape: ExpirationModelType, location_name: 'ExpirationModel', traits: {"smithy.api#documentation" => "<p>Indicates if the key material is configured to automatically expire. There are two\n      possible values for this field: <code>KEY_MATERIAL_EXPIRES</code> and\n        <code>KEY_MATERIAL_DOES_NOT_EXPIRE</code>. For any key material that expires, the expiration\n      date and time is indicated in <code>ValidTo</code>. This field is only present for symmetric\n      encryption KMS keys with <code>EXTERNAL</code> origin.</p>"}))
    RotationsListEntry.add_member(:valid_to, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'ValidTo', traits: {"smithy.api#documentation" => "<p>Date and time at which the key material expires. This field is only present for symmetric\n      encryption KMS keys with <code>EXTERNAL</code> origin in rotation list entries with an\n        <code>ExpirationModel</code> value of <code>KEY_MATERIAL_EXPIRES</code>.</p>"}))
    RotationsListEntry.add_member(:rotation_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'RotationDate', traits: {"smithy.api#documentation" => "<p>Date and time that the key material rotation completed. Formatted as Unix time. This field\n      is not present for the first key material or an imported key material in\n        <code>PENDING_ROTATION</code> state.</p>"}))
    RotationsListEntry.add_member(:rotation_type, Smithy::Schema::Shapes::ShapeRef.new(shape: RotationType, location_name: 'RotationType', traits: {"smithy.api#documentation" => "<p>Identifies whether the key material rotation was a scheduled <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/rotating-keys-enable-disable.html\">automatic rotation</a> or an <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/rotating-keys-on-demand.html\">on-demand\n        rotation</a>. This field is not present for the first key material or an imported key\n      material in <code>PENDING_ROTATION</code> state.</p>"}))
    RotationsListEntry.type = Types::RotationsListEntry
    ScheduleKeyDeletionRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>The unique identifier of the KMS key to delete.</p>\n         <p>Specify the key ID or key ARN of the KMS key.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>.</p>", "smithy.api#required" => {}}))
    ScheduleKeyDeletionRequest.add_member(:pending_window_in_days, Smithy::Schema::Shapes::ShapeRef.new(shape: PendingWindowInDaysType, location_name: 'PendingWindowInDays', traits: {"smithy.api#documentation" => "<p>The waiting period, specified in number of days. After the waiting period ends, KMS\n      deletes the KMS key.</p>\n         <p>If the KMS key is a multi-Region primary key with replica keys, the waiting period begins\n      when the last of its replica keys is deleted. Otherwise, the waiting period begins\n      immediately.</p>\n         <p>This value is optional. If you include a value, it must be between 7 and 30, inclusive. If\n      you do not include a value, it defaults to 30. You can use the <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/conditions-kms.html#conditions-kms-schedule-key-deletion-pending-window-in-days\">\n               <code>kms:ScheduleKeyDeletionPendingWindowInDays</code>\n            </a> condition key to further\n      constrain the values that principals can specify in the <code>PendingWindowInDays</code>\n      parameter.</p>"}))
    ScheduleKeyDeletionRequest.type = Types::ScheduleKeyDeletionRequest
    ScheduleKeyDeletionResponse.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/concepts.html#key-id-key-ARN\">key ARN</a>) of the KMS key whose deletion is scheduled.</p>"}))
    ScheduleKeyDeletionResponse.add_member(:deletion_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'DeletionDate', traits: {"smithy.api#documentation" => "<p>The date and time after which KMS deletes the KMS key.</p>\n         <p>If the KMS key is a multi-Region primary key with replica keys, this field does not\n      appear. The deletion date for the primary key isn't known until its last replica key is\n      deleted.</p>"}))
    ScheduleKeyDeletionResponse.add_member(:key_state, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyState, location_name: 'KeyState', traits: {"smithy.api#documentation" => "<p>The current status of the KMS key.</p>\n         <p>For more information about how key state affects the use of a KMS key, see\n      <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/key-state.html\">Key states of KMS keys</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    ScheduleKeyDeletionResponse.add_member(:pending_window_in_days, Smithy::Schema::Shapes::ShapeRef.new(shape: PendingWindowInDaysType, location_name: 'PendingWindowInDays', traits: {"smithy.api#documentation" => "<p>The waiting period before the KMS key is deleted. </p>\n         <p>If the KMS key is a multi-Region primary key with replicas, the waiting period begins when\n      the last of its replica keys is deleted. Otherwise, the waiting period begins\n      immediately.</p>"}))
    ScheduleKeyDeletionResponse.type = Types::ScheduleKeyDeletionResponse
    SignRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Identifies an asymmetric KMS key. KMS uses the private key in the asymmetric KMS key to\n      sign the message. The <code>KeyUsage</code> type of the KMS key must be\n        <code>SIGN_VERIFY</code>. To find the <code>KeyUsage</code> of a KMS key, use the <a>DescribeKey</a> operation.</p>\n         <p>To specify a KMS key, use its key ID, key ARN, alias name, or alias ARN. When using an alias name, prefix it with <code>\"alias/\"</code>. To specify a KMS key in a different Amazon Web Services account, you must use the key ARN or alias ARN.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias name: <code>alias/ExampleAlias</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias ARN: <code>arn:aws:kms:us-east-2:111122223333:alias/ExampleAlias</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>. To get the alias name and alias ARN, use <a>ListAliases</a>.</p>", "smithy.api#required" => {}}))
    SignRequest.add_member(:message, Smithy::Schema::Shapes::ShapeRef.new(shape: PlaintextType, location_name: 'Message', traits: {"smithy.api#documentation" => "<p>Specifies the message or message digest to sign. Messages can be 0-4096 bytes. To sign a\n      larger message, provide a message digest.</p>\n         <p>If you provide a message digest, use the <code>DIGEST</code> value of\n        <code>MessageType</code> to prevent the digest from being hashed again while signing.</p>", "smithy.api#required" => {}}))
    SignRequest.add_member(:message_type, Smithy::Schema::Shapes::ShapeRef.new(shape: MessageType, location_name: 'MessageType', traits: {"smithy.api#documentation" => "<p>Tells KMS whether the value of the <code>Message</code> parameter should be hashed as\n      part of the signing algorithm. Use <code>RAW</code> for unhashed messages; use\n        <code>DIGEST</code> for message digests, which are already hashed; use\n        <code>EXTERNAL_MU</code> for 64-byte representative μ used in ML-DSA signing as defined\n      in NIST FIPS 204 Section 6.2.</p>\n         <p>When the value of <code>MessageType</code> is <code>RAW</code>, KMS uses the standard\n      signing algorithm, which begins with a hash function. When the value is <code>DIGEST</code>,\n      KMS skips the hashing step in the signing algorithm. When the value is\n        <code>EXTERNAL_MU</code> KMS skips the concatenated hashing of the public key hash and the\n      message done in the ML-DSA signing algorithm.</p>\n         <important>\n            <p>Use the <code>DIGEST</code> or <code>EXTERNAL_MU</code> value only when the value of the\n          <code>Message</code> parameter is a message digest. If you use the <code>DIGEST</code>\n        value with an unhashed message, the security of the signing operation can be\n        compromised.</p>\n         </important>\n         <p>When the value of <code>MessageType</code> is <code>DIGEST</code>, the length of the\n        <code>Message</code> value must match the length of hashed messages for the specified\n      signing algorithm.</p>\n         <p>When the value of <code>MessageType</code> is <code>EXTERNAL_MU</code> the length of the\n        <code>Message</code> value must be 64 bytes.</p>\n         <p>You can submit a message digest and omit the <code>MessageType</code> or specify\n        <code>RAW</code> so the digest is hashed again while signing. However, this can cause\n      verification failures when verifying with a system that assumes a single hash.</p>\n         <p>The hashing algorithm that <code>Sign</code> uses is based on the\n        <code>SigningAlgorithm</code> value.</p>\n         <ul>\n            <li>\n               <p>Signing algorithms that end in SHA_256 use the SHA_256 hashing algorithm.</p>\n            </li>\n            <li>\n               <p>Signing algorithms that end in SHA_384 use the SHA_384 hashing algorithm.</p>\n            </li>\n            <li>\n               <p>Signing algorithms that end in SHA_512 use the SHA_512 hashing algorithm.</p>\n            </li>\n            <li>\n               <p>Signing algorithms that end in SHAKE_256 use the SHAKE_256 hashing algorithm.</p>\n            </li>\n            <li>\n               <p>SM2DSA uses the SM3 hashing algorithm. For details, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/offline-operations.html#key-spec-sm-offline-verification\">Offline\n            verification with SM2 key pairs</a>.</p>\n            </li>\n         </ul>"}))
    SignRequest.add_member(:grant_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: GrantTokenList, location_name: 'GrantTokens', traits: {"smithy.api#documentation" => "<p>A list of grant tokens.</p>\n         <p>Use a grant token when your permission to call this operation comes from a new grant that has not yet achieved <i>eventual consistency</i>. For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/grants.html#grant_token\">Grant token</a> and <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/using-grant-token.html\">Using a grant token</a> in the\n    <i>Key Management Service Developer Guide</i>.</p>"}))
    SignRequest.add_member(:signing_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: SigningAlgorithmSpec, location_name: 'SigningAlgorithm', traits: {"smithy.api#documentation" => "<p>Specifies the signing algorithm to use when signing the message. </p>\n         <p>Choose an algorithm that is compatible with the type and size of the specified asymmetric\n      KMS key. When signing with RSA key pairs, RSASSA-PSS algorithms are preferred. We include\n      RSASSA-PKCS1-v1_5 algorithms for compatibility with existing applications.</p>", "smithy.api#required" => {}}))
    SignRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBooleanType, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks if your request will succeed. <code>DryRun</code> is an optional parameter. </p>\n         <p>To learn more about how to use this parameter, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/testing-permissions.html\">Testing your permissions</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    SignRequest.type = Types::SignRequest
    SignResponse.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/concepts.html#key-id-key-ARN\">key ARN</a>) of the asymmetric KMS key that was used to sign the message.</p>"}))
    SignResponse.add_member(:signature, Smithy::Schema::Shapes::ShapeRef.new(shape: CiphertextType, location_name: 'Signature', traits: {"smithy.api#documentation" => "<p>The cryptographic signature that was generated for the message. </p>\n         <ul>\n            <li>\n               <p>When used with the supported RSA signing algorithms, the encoding of this value is\n          defined by <a href=\"https://tools.ietf.org/html/rfc8017\">PKCS #1 in RFC\n          8017</a>.</p>\n            </li>\n            <li>\n               <p>When used with the <code>ECDSA_SHA_256</code>, <code>ECDSA_SHA_384</code>, or\n            <code>ECDSA_SHA_512</code> signing algorithms, this value is a DER-encoded object as\n          defined by ANSI X9.62–2005 and <a href=\"https://tools.ietf.org/html/rfc3279#section-2.2.3\">RFC 3279 Section 2.2.3</a>.\n          This is the most commonly used signature format and is appropriate for most uses.\n          </p>\n            </li>\n         </ul>\n         <p>When you use the HTTP API or the Amazon Web Services CLI, the value is Base64-encoded. Otherwise, it is not Base64-encoded.</p>"}))
    SignResponse.add_member(:signing_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: SigningAlgorithmSpec, location_name: 'SigningAlgorithm', traits: {"smithy.api#documentation" => "<p>The signing algorithm that was used to sign the message.</p>"}))
    SignResponse.type = Types::SignResponse
