    Tag.add_member(:tag_value, Smithy::Schema::Shapes::ShapeRef.new(shape: TagValueType, location_name: 'TagValue', traits: {"smithy.api#documentation" => "<p>The value of the tag.</p>", "smithy.api#required" => {}}))
