    UntagResourceRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Identifies the KMS key from which you are removing tags.</p>\n         <p>Specify the key ID or key ARN of the KMS key.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>.</p>", "smithy.api#required" => {}}))
    UntagResourceRequest.add_member(:tag_keys, Smithy::Schema::Shapes::ShapeRef.new(shape: TagKeyList, location_name: 'TagKeys', traits: {"smithy.api#documentation" => "<p>One or more tag keys. Specify only the tag keys, not the tag values.</p>", "smithy.api#required" => {}}))
    UntagResourceRequest.type = Types::UntagResourceRequest
    UpdateAliasRequest.add_member(:alias_name, Smithy::Schema::Shapes::ShapeRef.new(shape: AliasNameType, location_name: 'AliasName', traits: {"smithy.api#documentation" => "<p>Identifies the alias that is changing its KMS key. This value must begin with\n        <code>alias/</code> followed by the alias name, such as <code>alias/ExampleAlias</code>. You\n      cannot use <code>UpdateAlias</code> to change the alias name.</p>\n         <important>\n            <p>Do not include confidential or sensitive information in this field. This field may be displayed in plaintext in CloudTrail logs and other output.</p>\n         </important>", "smithy.api#required" => {}}))
    UpdateAliasRequest.add_member(:target_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'TargetKeyId', traits: {"smithy.api#documentation" => "<p>Identifies the <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/concepts.html#customer-mgn-key\">customer managed key</a> to associate with the alias. You don't have permission to\n      associate an alias with an <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/concepts.html#aws-managed-key\">Amazon Web Services managed key</a>.</p>\n         <p>The KMS key must be in the same Amazon Web Services account and Region as the alias. Also, the new\n      target KMS key must be the same type as the current target KMS key (both symmetric or both\n      asymmetric or both HMAC) and they must have the same key usage. </p>\n         <p>Specify the key ID or key ARN of the KMS key.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>.</p>\n         <p>To verify that the alias is mapped to the correct KMS key, use <a>ListAliases</a>.</p>", "smithy.api#required" => {}}))
    UpdateAliasRequest.type = Types::UpdateAliasRequest
    UpdateCustomKeyStoreRequest.add_member(:custom_key_store_id, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomKeyStoreIdType, location_name: 'CustomKeyStoreId', traits: {"smithy.api#documentation" => "<p>Identifies the custom key store that you want to update. Enter the ID of the custom key\n      store. To find the ID of a custom key store, use the <a>DescribeCustomKeyStores</a> operation.</p>", "smithy.api#required" => {}}))
    UpdateCustomKeyStoreRequest.add_member(:new_custom_key_store_name, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomKeyStoreNameType, location_name: 'NewCustomKeyStoreName', traits: {"smithy.api#documentation" => "<p>Changes the friendly name of the custom key store to the value that you specify. The\n      custom key store name must be unique in the Amazon Web Services account.</p>\n         <important>\n            <p>Do not include confidential or sensitive information in this field. This field may be displayed in plaintext in CloudTrail logs and other output.</p>\n         </important>\n         <p>To change this value, an CloudHSM key store must be disconnected. An external key store can\n      be connected or disconnected.</p>"}))
    UpdateCustomKeyStoreRequest.add_member(:key_store_password, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyStorePasswordType, location_name: 'KeyStorePassword', traits: {"smithy.api#documentation" => "<p>Enter the current password of the <code>kmsuser</code> crypto user (CU) in the CloudHSM\n      cluster that is associated with the custom key store. This parameter is valid only for custom\n      key stores with a <code>CustomKeyStoreType</code> of <code>AWS_CLOUDHSM</code>.</p>\n         <p>This parameter tells KMS the current password of the <code>kmsuser</code> crypto user\n      (CU). It does not set or change the password of any users in the CloudHSM cluster.</p>\n         <p>To change this value, the CloudHSM key store must be disconnected.</p>"}))
    UpdateCustomKeyStoreRequest.add_member(:cloud_hsm_cluster_id, Smithy::Schema::Shapes::ShapeRef.new(shape: CloudHsmClusterIdType, location_name: 'CloudHsmClusterId', traits: {"smithy.api#documentation" => "<p>Associates the custom key store with a related CloudHSM cluster. This parameter is valid only\n      for custom key stores with a <code>CustomKeyStoreType</code> of\n      <code>AWS_CLOUDHSM</code>.</p>\n         <p>Enter the cluster ID of the cluster that you used to create the custom key store or a\n      cluster that shares a backup history and has the same cluster certificate as the original\n      cluster. You cannot use this parameter to associate a custom key store with an unrelated\n      cluster. In addition, the replacement cluster must <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/create-keystore.html#before-keystore\">fulfill the requirements</a> for\n      a cluster associated with a custom key store. To view the cluster certificate of a cluster,\n      use the <a href=\"https://docs.aws.amazon.com/cloudhsm/latest/APIReference/API_DescribeClusters.html\">DescribeClusters</a> operation.</p>\n         <p>To change this value, the CloudHSM key store must be disconnected.</p>"}))
    UpdateCustomKeyStoreRequest.add_member(:xks_proxy_uri_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: XksProxyUriEndpointType, location_name: 'XksProxyUriEndpoint', traits: {"smithy.api#documentation" => "<p>Changes the URI endpoint that KMS uses to connect to your external key store proxy (XKS\n      proxy). This parameter is valid only for custom key stores with a\n        <code>CustomKeyStoreType</code> of <code>EXTERNAL_KEY_STORE</code>.</p>\n         <p>For external key stores with an <code>XksProxyConnectivity</code> value of\n        <code>PUBLIC_ENDPOINT</code>, the protocol must be HTTPS.</p>\n         <p>For external key stores with an <code>XksProxyConnectivity</code> value of\n        <code>VPC_ENDPOINT_SERVICE</code>, specify <code>https://</code> followed by the private DNS\n      name associated with the VPC endpoint service. Each external key store must use a different\n      private DNS name.</p>\n         <p>The combined <code>XksProxyUriEndpoint</code> and <code>XksProxyUriPath</code> values must\n      be unique in the Amazon Web Services account and Region.</p>\n         <p>To change this value, the external key store must be disconnected.</p>"}))
    UpdateCustomKeyStoreRequest.add_member(:xks_proxy_uri_path, Smithy::Schema::Shapes::ShapeRef.new(shape: XksProxyUriPathType, location_name: 'XksProxyUriPath', traits: {"smithy.api#documentation" => "<p>Changes the base path to the proxy APIs for this external key store. To find this value,\n      see the documentation for your external key manager and external key store proxy (XKS proxy).\n      This parameter is valid only for custom key stores with a <code>CustomKeyStoreType</code> of\n        <code>EXTERNAL_KEY_STORE</code>.</p>\n         <p>The value must start with <code>/</code> and must end with <code>/kms/xks/v1</code>, where\n        <code>v1</code> represents the version of the KMS external key store proxy API. You can\n      include an optional prefix between the required elements such as\n          <code>/<i>example</i>/kms/xks/v1</code>.</p>\n         <p>The combined <code>XksProxyUriEndpoint</code> and <code>XksProxyUriPath</code> values must\n      be unique in the Amazon Web Services account and Region.</p>\n         <p>You can change this value when the external key store is connected or disconnected.</p>"}))
    UpdateCustomKeyStoreRequest.add_member(:xks_proxy_vpc_endpoint_service_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XksProxyVpcEndpointServiceNameType, location_name: 'XksProxyVpcEndpointServiceName', traits: {"smithy.api#documentation" => "<p>Changes the name that KMS uses to identify the Amazon VPC endpoint service for your external\n      key store proxy (XKS proxy). This parameter is valid when the <code>CustomKeyStoreType</code>\n      is <code>EXTERNAL_KEY_STORE</code> and the <code>XksProxyConnectivity</code> is\n        <code>VPC_ENDPOINT_SERVICE</code>.</p>\n         <p>To change this value, the external key store must be disconnected.</p>"}))
    UpdateCustomKeyStoreRequest.add_member(:xks_proxy_authentication_credential, Smithy::Schema::Shapes::ShapeRef.new(shape: XksProxyAuthenticationCredentialType, location_name: 'XksProxyAuthenticationCredential', traits: {"smithy.api#documentation" => "<p>Changes the credentials that KMS uses to sign requests to the external key store proxy\n      (XKS proxy). This parameter is valid only for custom key stores with a\n        <code>CustomKeyStoreType</code> of <code>EXTERNAL_KEY_STORE</code>.</p>\n         <p>You must specify both the <code>AccessKeyId</code> and <code>SecretAccessKey</code> value\n      in the authentication credential, even if you are only updating one value.</p>\n         <p>This parameter doesn't establish or change your authentication credentials on the proxy.\n      It just tells KMS the credential that you established with your external key store proxy.\n      For example, if you rotate the credential on your external key store proxy, you can use this\n      parameter to update the credential in KMS.</p>\n         <p>You can change this value when the external key store is connected or disconnected.</p>"}))
    UpdateCustomKeyStoreRequest.add_member(:xks_proxy_connectivity, Smithy::Schema::Shapes::ShapeRef.new(shape: XksProxyConnectivityType, location_name: 'XksProxyConnectivity', traits: {"smithy.api#documentation" => "<p>Changes the connectivity setting for the external key store. To indicate that the external\n      key store proxy uses a Amazon VPC endpoint service to communicate with KMS, specify\n        <code>VPC_ENDPOINT_SERVICE</code>. Otherwise, specify <code>PUBLIC_ENDPOINT</code>.</p>\n         <p>If you change the <code>XksProxyConnectivity</code> to <code>VPC_ENDPOINT_SERVICE</code>,\n      you must also change the <code>XksProxyUriEndpoint</code> and add an\n        <code>XksProxyVpcEndpointServiceName</code> value. </p>\n         <p>If you change the <code>XksProxyConnectivity</code> to <code>PUBLIC_ENDPOINT</code>, you\n      must also change the <code>XksProxyUriEndpoint</code> and specify a null or empty string for\n      the <code>XksProxyVpcEndpointServiceName</code> value.</p>\n         <p>To change this value, the external key store must be disconnected.</p>"}))
    UpdateCustomKeyStoreRequest.type = Types::UpdateCustomKeyStoreRequest
    UpdateCustomKeyStoreResponse.type = Types::UpdateCustomKeyStoreResponse
    UpdateKeyDescriptionRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Updates the description of the specified KMS key.</p>\n         <p>Specify the key ID or key ARN of the KMS key.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>.</p>", "smithy.api#required" => {}}))
    UpdateKeyDescriptionRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: DescriptionType, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>New description for the KMS key.</p>\n         <important>\n            <p>Do not include confidential or sensitive information in this field. This field may be displayed in plaintext in CloudTrail logs and other output.</p>\n         </important>", "smithy.api#required" => {}}))
    UpdateKeyDescriptionRequest.type = Types::UpdateKeyDescriptionRequest
    UpdatePrimaryRegionRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Identifies the current primary key. When the operation completes, this KMS key will be a\n      replica key.</p>\n         <p>Specify the key ID or key ARN of a multi-Region primary key.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>mrk-1234abcd12ab34cd56ef1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/mrk-1234abcd12ab34cd56ef1234567890ab</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>.</p>", "smithy.api#required" => {}}))
    UpdatePrimaryRegionRequest.add_member(:primary_region, Smithy::Schema::Shapes::ShapeRef.new(shape: RegionType, location_name: 'PrimaryRegion', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services Region of the new primary key. Enter the Region ID, such as\n        <code>us-east-1</code> or <code>ap-southeast-2</code>. There must be an existing replica key\n      in this Region. </p>\n         <p>When the operation completes, the multi-Region key in this Region will be the primary\n      key.</p>", "smithy.api#required" => {}}))
    UpdatePrimaryRegionRequest.type = Types::UpdatePrimaryRegionRequest
    VerifyMacRequest.add_member(:message, Smithy::Schema::Shapes::ShapeRef.new(shape: PlaintextType, location_name: 'Message', traits: {"smithy.api#documentation" => "<p>The message that will be used in the verification. Enter the same message that was used to\n      generate the HMAC.</p>\n         <p>\n            <a>GenerateMac</a> and <code>VerifyMac</code> do not provide special handling\n      for message digests. If you generated an HMAC for a hash digest of a message, you must verify\n      the HMAC for the same hash digest.</p>", "smithy.api#required" => {}}))
    VerifyMacRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>The KMS key that will be used in the verification.</p>\n         <p>Enter a key ID of the KMS key that was used to generate the HMAC. If you identify a\n      different KMS key, the <code>VerifyMac</code> operation fails.</p>", "smithy.api#required" => {}}))
    VerifyMacRequest.add_member(:mac_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: MacAlgorithmSpec, location_name: 'MacAlgorithm', traits: {"smithy.api#documentation" => "<p>The MAC algorithm that will be used in the verification. Enter the same MAC algorithm that\n      was used to compute the HMAC. This algorithm must be supported by the HMAC KMS key identified\n      by the <code>KeyId</code> parameter.</p>", "smithy.api#required" => {}}))
    VerifyMacRequest.add_member(:mac, Smithy::Schema::Shapes::ShapeRef.new(shape: CiphertextType, location_name: 'Mac', traits: {"smithy.api#documentation" => "<p>The HMAC to verify. Enter the HMAC that was generated by the <a>GenerateMac</a>\n      operation when you specified the same message, HMAC KMS key, and MAC algorithm as the values\n      specified in this request.</p>", "smithy.api#required" => {}}))
    VerifyMacRequest.add_member(:grant_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: GrantTokenList, location_name: 'GrantTokens', traits: {"smithy.api#documentation" => "<p>A list of grant tokens.</p>\n         <p>Use a grant token when your permission to call this operation comes from a new grant that has not yet achieved <i>eventual consistency</i>. For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/grants.html#grant_token\">Grant token</a> and <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/using-grant-token.html\">Using a grant token</a> in the\n    <i>Key Management Service Developer Guide</i>.</p>"}))
    VerifyMacRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBooleanType, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks if your request will succeed. <code>DryRun</code> is an optional parameter. </p>\n         <p>To learn more about how to use this parameter, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/testing-permissions.html\">Testing your permissions</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    VerifyMacRequest.type = Types::VerifyMacRequest
    VerifyMacResponse.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>The HMAC KMS key used in the verification.</p>"}))
    VerifyMacResponse.add_member(:mac_valid, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'MacValid', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>A Boolean value that indicates whether the HMAC was verified. A value of <code>True</code>\n      indicates that the HMAC (<code>Mac</code>) was generated with the specified\n        <code>Message</code>, HMAC KMS key (<code>KeyID</code>) and\n      <code>MacAlgorithm.</code>.</p>\n         <p>If the HMAC is not verified, the <code>VerifyMac</code> operation fails with a\n        <code>KMSInvalidMacException</code> exception. This exception indicates that one or more of\n      the inputs changed since the HMAC was computed.</p>"}))
    VerifyMacResponse.add_member(:mac_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: MacAlgorithmSpec, location_name: 'MacAlgorithm', traits: {"smithy.api#documentation" => "<p>The MAC algorithm used in the verification.</p>"}))
    VerifyMacResponse.type = Types::VerifyMacResponse
    VerifyRequest.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>Identifies the asymmetric KMS key that will be used to verify the signature. This must be\n      the same KMS key that was used to generate the signature. If you specify a different KMS key,\n      the signature verification fails.</p>\n         <p>To specify a KMS key, use its key ID, key ARN, alias name, or alias ARN. When using an alias name, prefix it with <code>\"alias/\"</code>. To specify a KMS key in a different Amazon Web Services account, you must use the key ARN or alias ARN.</p>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Key ARN: <code>arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias name: <code>alias/ExampleAlias</code>\n               </p>\n            </li>\n            <li>\n               <p>Alias ARN: <code>arn:aws:kms:us-east-2:111122223333:alias/ExampleAlias</code>\n               </p>\n            </li>\n         </ul>\n         <p>To get the key ID and key ARN for a KMS key, use <a>ListKeys</a> or <a>DescribeKey</a>. To get the alias name and alias ARN, use <a>ListAliases</a>.</p>", "smithy.api#required" => {}}))
    VerifyRequest.add_member(:message, Smithy::Schema::Shapes::ShapeRef.new(shape: PlaintextType, location_name: 'Message', traits: {"smithy.api#documentation" => "<p>Specifies the message that was signed. You can submit a raw message of up to 4096 bytes,\n      or a hash digest of the message. If you submit a digest, use the <code>MessageType</code>\n      parameter with a value of <code>DIGEST</code>.</p>\n         <p>If the message specified here is different from the message that was signed, the signature\n      verification fails. A message and its hash digest are considered to be the same\n      message.</p>", "smithy.api#required" => {}}))
    VerifyRequest.add_member(:message_type, Smithy::Schema::Shapes::ShapeRef.new(shape: MessageType, location_name: 'MessageType', traits: {"smithy.api#documentation" => "<p>Tells KMS whether the value of the <code>Message</code> parameter should be hashed as\n      part of the signing algorithm. Use <code>RAW</code> for unhashed messages; use\n        <code>DIGEST</code> for message digests, which are already hashed; use\n        <code>EXTERNAL_MU</code> for 64-byte representative μ used in ML-DSA signing as defined\n      in NIST FIPS 204 Section 6.2.</p>\n         <p>When the value of <code>MessageType</code> is <code>RAW</code>, KMS uses the standard\n      signing algorithm, which begins with a hash function. When the value is <code>DIGEST</code>,\n      KMS skips the hashing step in the signing algorithm. When the value is\n        <code>EXTERNAL_MU</code> KMS skips the concatenated hashing of the public key hash and the\n      message done in the ML-DSA signing algorithm.</p>\n         <important>\n            <p>Use the <code>DIGEST</code> or <code>EXTERNAL_MU</code> value only when the value of the\n          <code>Message</code> parameter is a message digest. If you use the <code>DIGEST</code>\n        value with an unhashed message, the security of the signing operation can be\n        compromised.</p>\n         </important>\n         <p>When the value of <code>MessageType</code> is <code>DIGEST</code>, the length of the\n        <code>Message</code> value must match the length of hashed messages for the specified\n      signing algorithm.</p>\n         <p>When the value of <code>MessageType</code> is <code>EXTERNAL_MU</code> the length of the\n        <code>Message</code> value must be 64 bytes.</p>\n         <p>You can submit a message digest and omit the <code>MessageType</code> or specify\n        <code>RAW</code> so the digest is hashed again while signing. However, if the signed message\n      is hashed once while signing, but twice while verifying, verification fails, even when the\n      message hasn't changed.</p>\n         <p>The hashing algorithm that <code>Verify</code> uses is based on the\n        <code>SigningAlgorithm</code> value.</p>\n         <ul>\n            <li>\n               <p>Signing algorithms that end in SHA_256 use the SHA_256 hashing algorithm.</p>\n            </li>\n            <li>\n               <p>Signing algorithms that end in SHA_384 use the SHA_384 hashing algorithm.</p>\n            </li>\n            <li>\n               <p>Signing algorithms that end in SHA_512 use the SHA_512 hashing algorithm.</p>\n            </li>\n            <li>\n               <p>Signing algorithms that end in SHAKE_256 use the SHAKE_256 hashing algorithm.</p>\n            </li>\n            <li>\n               <p>SM2DSA uses the SM3 hashing algorithm. For details, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/offline-operations.html#key-spec-sm-offline-verification\">Offline\n            verification with SM2 key pairs</a>.</p>\n            </li>\n         </ul>"}))
    VerifyRequest.add_member(:signature, Smithy::Schema::Shapes::ShapeRef.new(shape: CiphertextType, location_name: 'Signature', traits: {"smithy.api#documentation" => "<p>The signature that the <code>Sign</code> operation generated.</p>", "smithy.api#required" => {}}))
    VerifyRequest.add_member(:signing_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: SigningAlgorithmSpec, location_name: 'SigningAlgorithm', traits: {"smithy.api#documentation" => "<p>The signing algorithm that was used to sign the message. If you submit a different\n      algorithm, the signature verification fails.</p>", "smithy.api#required" => {}}))
    VerifyRequest.add_member(:grant_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: GrantTokenList, location_name: 'GrantTokens', traits: {"smithy.api#documentation" => "<p>A list of grant tokens.</p>\n         <p>Use a grant token when your permission to call this operation comes from a new grant that has not yet achieved <i>eventual consistency</i>. For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/grants.html#grant_token\">Grant token</a> and <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/using-grant-token.html\">Using a grant token</a> in the\n    <i>Key Management Service Developer Guide</i>.</p>"}))
    VerifyRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableBooleanType, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks if your request will succeed. <code>DryRun</code> is an optional parameter. </p>\n         <p>To learn more about how to use this parameter, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/testing-permissions.html\">Testing your permissions</a> in the <i>Key Management Service Developer Guide</i>.</p>"}))
    VerifyRequest.type = Types::VerifyRequest
    VerifyResponse.add_member(:key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyIdType, location_name: 'KeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/concepts.html#key-id-key-ARN\">key ARN</a>) of the asymmetric KMS key that was used to verify the signature.</p>"}))
    VerifyResponse.add_member(:signature_valid, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'SignatureValid', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>A Boolean value that indicates whether the signature was verified. A value of\n        <code>True</code> indicates that the <code>Signature</code> was produced by signing the\n        <code>Message</code> with the specified <code>KeyID</code> and\n        <code>SigningAlgorithm.</code> If the signature is not verified, the <code>Verify</code>\n      operation fails with a <code>KMSInvalidSignatureException</code> exception. </p>"}))
    VerifyResponse.add_member(:signing_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: SigningAlgorithmSpec, location_name: 'SigningAlgorithm', traits: {"smithy.api#documentation" => "<p>The signing algorithm that was used to verify the signature.</p>"}))
