    XksProxyConfigurationType.add_member(:access_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XksProxyAuthenticationAccessKeyIdType, location_name: 'AccessKeyId', traits: {"smithy.api#documentation" => "<p>The part of the external key store <a href=\"https://docs.aws.amazon.com/kms/latest/APIReference/API_CreateCustomKeyStore.html#KMS-CreateCustomKeyStore-request-XksProxyAuthenticationCredential\">proxy authentication credential</a> that uniquely identifies the secret access\n      key.</p>"}))
    XksProxyConfigurationType.add_member(:uri_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: XksProxyUriEndpointType, location_name: 'UriEndpoint', traits: {"smithy.api#documentation" => "<p>The URI endpoint for the external key store proxy.</p>\n         <p>If the external key store proxy has a public endpoint, it is displayed here.</p>\n         <p>If the external key store proxy uses an Amazon VPC endpoint service name, this field displays\n      the private DNS name associated with the VPC endpoint service.</p>"}))
    XksProxyConfigurationType.add_member(:uri_path, Smithy::Schema::Shapes::ShapeRef.new(shape: XksProxyUriPathType, location_name: 'UriPath', traits: {"smithy.api#documentation" => "<p>The path to the external key store proxy APIs.</p>"}))
    XksProxyConfigurationType.add_member(:vpc_endpoint_service_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XksProxyVpcEndpointServiceNameType, location_name: 'VpcEndpointServiceName', traits: {"smithy.api#documentation" => "<p>The Amazon VPC endpoint service used to communicate with the external key store proxy. This\n      field appears only when the external key store proxy uses an Amazon VPC endpoint service to\n      communicate with KMS.</p>"}))
